// Debug stats for convex_intersect_fast paths.
static struct FastStats {
    long long proper_pt = 0;    // proper intersection point returned
    long long degen_null = 0;  // CGAL::intersection returned null
    long long degen_seg = 0;   // CGAL::intersection returned segment (collinear)
