    Epeck::Point_2 ea = conv_to_exact(a);
    Epeck::Point_2 eb = conv_to_exact(b);
    Epeck::Point_2 ec = conv_to_exact(c);
    if (CGAL::orientation(ea, eb, ec) != CGAL::COLLINEAR) return false;
    // Exact dominance test — convert to Epeck for precision.
    if (CGAL::abs(eb.x() - ea.x()) >= CGAL::abs(eb.y() - ea.y())) {
        return (ea.x() <= ec.x() && ec.x() <= eb.x()) ||
               (ea.x() >= ec.x() && ec.x() >= eb.x());
