                    const Point& c, const Point& d) {
    Epeck::FT ax(a.x()), ay(a.y()), bx(b.x()), by(b.y()),
              cx(c.x()), cy(c.y()), dx(d.x()), dy(d.y());
    Epeck::FT ux = bx - ax, uy = by - ay;
    Epeck::FT vx = dx - cx, vy = dy - cy;
    Epeck::FT s = ux * vx + uy * vy;
    if (s > 0) return  1;
