// Boost.Geometry polygon type for intersection.
namespace bg = boost::geometry;
using BgPoint = bg::model::d2::point_xy<double>;
using BgPolygon = bg::model::polygon<BgPoint, true, true>;

// Convert our Point vector to a Boost.Geometry polygon.
static BgPolygon to_bg_polygon(const std::vector<Point>& pts) {
    BgPolygon poly;
    for (const auto& p : pts) {
        bg::append(poly, BgPoint(CGAL::to_double(p.x()), CGAL::to_double(p.y())));
    }
    bg::append(poly, BgPoint(CGAL::to_double(pts[0].x()), CGAL::to_double(pts[0].y())));
    return poly;
}

// Convert a Boost.Geometry polygon back to our Point vector (normalized CCW).
static std::vector<Point> from_bg_polygon(const BgPolygon& poly) {
    std::vector<Point> out;
    for (const auto& pt : poly.outer()) {
        out.emplace_back(pt.x(), pt.y());
    }
    // Remove the closing duplicate if present.
    if (out.size() > 1 && out.front() == out.back())
        out.pop_back();
    return out;
}

// Normalize a polygon to CCW order.
static std::vector<Point> normalize_convex_polygon(std::vector<Point> poly) {
    if (poly.size() < 3) return {};
    double area = kernel_signed_area(poly);
    if (area < 0) {
        std::reverse(poly.begin(), poly.end());
    }
    return poly;
}

static std::vector<Point> intersect_convex_polygons(const std::vector<Point>& lhs,
                                                    const std::vector<Point>& rhs) {
    BgPolygon lhs_polygon = to_bg_polygon(lhs);
    BgPolygon rhs_polygon = to_bg_polygon(rhs);
    std::vector<BgPolygon> output;
    boost::geometry::intersection(lhs_polygon, rhs_polygon, output);

    if (output.empty()) {
        return {};
    }

    auto best = std::max_element(output.begin(), output.end(), [](const BgPolygon& a, const BgPolygon& b) {
        return boost::geometry::area(a) < boost::geometry::area(b);
    });

    return normalize_convex_polygon(from_bg_polygon(*best));
}

