// Filtered_kernel uses double arithmetic but filters to exact when needed
using IntersectKernel = CGAL::Filtered_kernel<CGAL::Simple_cartesian<double>>;

// Algorithm: collect all boundary points + segment intersections, then convex hull
// - Point-in-polygon tests (O(|P|+|Q|) each)
