// Convex polygon intersection using boundary point collection + convex hull
// Collects all boundary points and intersection points, then computes convex hull.
static std::vector<Point> intersect_convex_polygons(const std::vector<Point>& lhs,
                                                   const std::vector<Point>& rhs) {
    std::vector<IntersectPoint> P_verts, Q_verts;
    P_verts.reserve(lhs.size());
    Q_verts.reserve(rhs.size());
    for (const auto& p : lhs) P_verts.push_back(to_intersect(p));
    for (const auto& p : rhs) Q_verts.push_back(to_intersect(p));

    if (P_verts.size() < 3 || Q_verts.size() < 3) return {};

    int n = (int)P_verts.size();
    int m = (int)Q_verts.size();

    // Collect candidates into a vector, sort and deduplicate.
    // Using vector+sort is faster than std::set because:
    // 1. No tree node allocations per insert
    // 2. Better cache locality during traversal
    // 3. Single sort pass is O(k log k) vs k * O(log k) for set
    std::vector<std::pair<double,double>> keys;
    std::vector<IntersectPoint> candidates;
    candidates.reserve(n + m + n * m);

    auto add_unique = [&](const IntersectPoint& p) {
        double x = CGAL::to_double(p.x());
        double y = CGAL::to_double(p.y());
        keys.emplace_back(x, y);
        candidates.push_back(p);
    };

    for (int i = 0; i < n; i++) {
        if (point_in_polygon(P_verts[i], Q_verts)) {
            add_unique(P_verts[i]);
        }
    }
    for (int j = 0; j < m; j++) {
        if (point_in_polygon(Q_verts[j], P_verts)) {
            add_unique(Q_verts[j]);
        }
    }

    for (int i = 0; i < n; i++) {
        const IntersectPoint& p1 = P_verts[i];
        const IntersectPoint& p2 = P_verts[(i + 1) % n];
        for (int j = 0; j < m; j++) {
            const IntersectPoint& q1 = Q_verts[j];
            const IntersectPoint& q2 = Q_verts[(j + 1) % m];
            auto inter = segment_intersection(p1, p2, q1, q2);
            if (inter) {
                add_unique(*inter);
            }
        }
    }

    if (candidates.size() < 3) return {};

    // Sort and deduplicate: O(k log k) with no allocations
    std::vector<std::pair<double,double>> sorted_keys = keys;
    std::sort(sorted_keys.begin(), sorted_keys.end());
    sorted_keys.erase(std::unique(sorted_keys.begin(), sorted_keys.end(),
                                  [](const auto& a, const auto& b) {
                                      return a.first == b.first && a.second == b.second;
                                  }), sorted_keys.end());

    if (sorted_keys.size() < 3) return {};

    // Build final candidate list keeping only unique points
    std::vector<IntersectPoint> unique_candidates;
    unique_candidates.reserve(sorted_keys.size());
    std::sort(keys.begin(), keys.end());
    size_t idx = 0;
    for (size_t i = 0; i < keys.size(); i++) {
        if (i == 0 || keys[i] != keys[i-1]) {
            unique_candidates.push_back(candidates[i]);
        }
    }

    std::vector<IntersectPoint> hull;
    CGAL::convex_hull_2(unique_candidates.begin(), unique_candidates.end(),
                        std::back_inserter(hull));

    if (hull.size() < 3) return {};

    std::vector<Point> result;
    result.reserve(hull.size());
    for (const auto& hp : hull) {
        result.push_back(from_intersect(hp));
    }
    return result;
}

