// Compare the two convex-polygon intersection algorithms on identical inputs.
//
// Usage: ./compare_intersect [N]
// Reads N random convex polygons and intersects every pair, dumping results.

#include <CGAL/Simple_cartesian.h>
#include <CGAL/point_generators_2.h>
#include <CGAL/convex_hull_2.h>
#include <CGAL/Polygon_2.h>
#include <CGAL/Boolean_set_operations_2.h>
#include <random>
#include <iostream>
#include <fstream>
#include <vector>
#include <optional>
#include <utility>

using K = CGAL::Simple_cartesian<double>;
using Point = K::Point_2;
using Segment = K::Segment_2;
using IntersectPoint = Point;
using Polygon = CGAL::Polygon_2<K>;
using Polygon_with_holes = CGAL::Polygon_with_holes_2<K>;

static bool point_in_polygon(const Point& p, const std::vector<Point>& poly) {
    int n = (int)poly.size();
    for (int i = 0; i < n; i++) {
        const Point& a = poly[i];
        const Point& b = poly[(i + 1) % n];
        if (!CGAL::left_turn(a, b, p)) return false;
    }
    return true;
}

static std::optional<Point> segment_intersection(const Point& p1, const Point& p2,
                                                 const Point& q1, const Point& q2) {
    auto inter = CGAL::intersection(Segment(p1, p2), Segment(q1, q2));
    if (inter && std::holds_alternative<Point>(*inter)) {
        return std::get<Point>(*inter);
    }
    return std::nullopt;
}

// Algorithm A: boundary points + convex hull
static std::vector<Point> intersect_convex_polygons_A(const std::vector<Point>& lhs,
                                                      const std::vector<Point>& rhs) {
    int n = (int)lhs.size();
    int m = (int)rhs.size();
    if (n < 3 || m < 3) return {};

    std::vector<std::pair<std::pair<double,double>, Point>> pairs;
    pairs.reserve(n + m + n * m);

    auto add_point = [&](const Point& p) {
        double x = CGAL::to_double(p.x());
        double y = CGAL::to_double(p.y());
        pairs.emplace_back(std::make_pair(x, y), p);
    };

    for (int i = 0; i < n; i++) {
        if (point_in_polygon(lhs[i], rhs)) add_point(lhs[i]);
    }
    for (int j = 0; j < m; j++) {
        if (point_in_polygon(rhs[j], lhs)) add_point(rhs[j]);
    }

    for (int i = 0; i < n; i++) {
        const Point& p1 = lhs[i];
        const Point& p2 = lhs[(i + 1) % n];
        for (int j = 0; j < m; j++) {
            const Point& q1 = rhs[j];
            const Point& q2 = rhs[(j + 1) % m];
            auto inter = segment_intersection(p1, p2, q1, q2);
            if (inter) {
                double x = CGAL::to_double(inter->x());
                double y = CGAL::to_double(inter->y());
                pairs.emplace_back(std::make_pair(x, y), *inter);
            }
        }
    }

    if (pairs.empty()) return {};

    std::sort(pairs.begin(), pairs.end(),
              [](const auto& a, const auto& b) {
                  if (a.first.first != b.first.first) return a.first.first < b.first.first;
                  return a.first.second < b.first.second;
              });

    std::vector<Point> candidates;
    candidates.reserve(pairs.size());
    candidates.push_back(pairs[0].second);
    for (size_t i = 1; i < pairs.size(); i++) {
        if (pairs[i].first != pairs[i-1].first) candidates.push_back(pairs[i].second);
    }

    if (candidates.size() < 3) return {};

    std::vector<Point> hull;
    CGAL::convex_hull_2(candidates.begin(), candidates.end(), std::back_inserter(hull));
    return hull;
}

// Algorithm B: Sutherland-Hodgman (faithful to the in-tree convex_intersect_fast,
// but using Simple_cartesian<double> to avoid per-vertex exact conversions)
static std::optional<Point> line_intersect(const Point& a, const Point& b,
                                           const Point& c, const Point& d) {
    auto inter = CGAL::intersection(Segment(a, b), Segment(c, d));
    if (inter && std::holds_alternative<Point>(*inter)) {
        return std::get<Point>(*inter);
    }
    return std::nullopt;
}

static std::vector<Point> clip_halfplane(const std::vector<Point>& subject,
                                         const Point& a, const Point& b) {
    int n = (int)subject.size();
    if (n == 0) return {};

    std::vector<Point> out;
    out.reserve(n + 1);

    for (int i = 0; i < n; ++i) {
        const Point& cur  = subject[i];
        const Point& prev = subject[(i + n - 1) % n];
        auto o_cur  = CGAL::orientation(a, b, cur);
        auto o_prev = CGAL::orientation(a, b, prev);
        bool cur_in  = (o_cur  != CGAL::RIGHT_TURN);
        bool prev_in = (o_prev != CGAL::RIGHT_TURN);

        if (cur_in) {
            if (!prev_in) {
                if (auto ip = line_intersect(a, b, prev, cur)) out.push_back(*ip);
            }
            out.push_back(cur);
        } else if (prev_in) {
            if (auto ip = line_intersect(a, b, prev, cur)) out.push_back(*ip);
        }
    }
    return out;
}

static double signed_area(const std::vector<Point>& P) {
    double s = 0;
    int n = (int)P.size();
    for (int i = 0; i < n; i++) {
        const Point& a = P[i];
        const Point& b = P[(i + 1) % n];
        s += a.x() * b.y() - b.x() * a.y();
    }
    return s;
}

static std::vector<Point> intersect_convex_polygons_B(const std::vector<Point>& Pin,
                                                      const std::vector<Point>& Qin) {
    if (Pin.size() < 3 || Qin.size() < 3) return {};

    std::vector<Point> P, Q;
    if (signed_area(Pin) < 0) { P.assign(Pin.rbegin(), Pin.rend()); }
    else                       { P = Pin; }
    if (signed_area(Qin) < 0) { Q.assign(Qin.rbegin(), Qin.rend()); }
    else                       { Q = Qin; }

    // Containment shortcuts
    if (point_in_polygon(P[0], Q)) {
        bool all_in = true;
        for (const auto& v : P) if (!point_in_polygon(v, Q)) { all_in = false; break; }
        if (all_in) return P;
    }
    if (point_in_polygon(Q[0], P)) {
        bool all_in = true;
        for (const auto& v : Q) if (!point_in_polygon(v, P)) { all_in = false; break; }
        if (all_in) return Q;
    }

    std::vector<Point> running = P;
    int m = (int)Q.size();
    for (int i = 0; i < m; ++i) {
        running = clip_halfplane(running, Q[i], Q[(i + 1) % m]);
        if (running.size() < 3) return {};
    }
    return running;
}

// Generate a random convex polygon with N vertices inside [0, 100]^2
static std::vector<Point> random_convex(std::mt19937& rng, int n) {
    std::uniform_real_distribution<double> dist(0.0, 100.0);
    std::vector<Point> pts;
    pts.reserve(n);
    for (int i = 0; i < n * 4; i++) {
        pts.push_back(Point(dist(rng), dist(rng)));
    }
    std::vector<Point> hull;
    CGAL::convex_hull_2(pts.begin(), pts.end(), std::back_inserter(hull));
    if ((int)hull.size() > n) hull.resize(n);
    return hull;
}

int main(int argc, char** argv) {
    int N = (argc > 1) ? std::atoi(argv[1]) : 100;
    std::mt19937 rng(42);

    int same = 0, diff = 0, empty_a = 0, empty_b = 0;
    double total_area_diff = 0.0;

    std::ofstream diff_log("intersect_diff.txt");

    for (int trial = 0; trial < N; trial++) {
        std::uniform_int_distribution<int> ndist(3, 30);
        std::vector<Point> P = random_convex(rng, ndist(rng));
        std::vector<Point> Q = random_convex(rng, ndist(rng));

        auto A = intersect_convex_polygons_A(P, Q);
        auto B = intersect_convex_polygons_B(P, Q);

        bool a_empty = A.size() < 3;
        bool b_empty = B.size() < 3;
        if (a_empty) empty_a++;
        if (b_empty) empty_b++;

        if (a_empty && b_empty) { same++; continue; }
        if (a_empty != b_empty) {
            diff++;
            diff_log << "Trial " << trial << ": A empty=" << a_empty << ", B empty=" << b_empty << "\n";
            diff_log << "  P size=" << P.size() << ", Q size=" << Q.size() << "\n";
            continue;
        }

        double area_a = std::fabs(signed_area(A));
        double area_b = std::fabs(signed_area(B));
        total_area_diff += std::fabs(area_a - area_b);

        // Check if A == B (up to vertex order)
        bool match = (A.size() == B.size());
        if (match) {
            std::sort(A.begin(), A.end(), [](const Point& a, const Point& b) {
                if (a.x() != b.x()) return a.x() < b.x();
                return a.y() < b.y();
            });
            std::sort(B.begin(), B.end(), [](const Point& a, const Point& b) {
                if (a.x() != b.x()) return a.x() < b.x();
                return a.y() < b.y();
            });
            for (size_t i = 0; i < A.size(); i++) {
                double dx = CGAL::to_double(A[i].x() - B[i].x());
                double dy = CGAL::to_double(A[i].y() - B[i].y());
                if (dx*dx + dy*dy > 1e-12) { match = false; break; }
            }
        }

        if (match) {
            same++;
        } else {
            diff++;
            if (diff <= 5) {
                diff_log << "Trial " << trial << ": A has " << A.size() << " verts, B has " << B.size() << " verts\n";
                diff_log << "  area A=" << area_a << ", B=" << area_b << "\n";
                diff_log << "  A vertices:\n";
                for (const auto& v : A) diff_log << "    (" << v.x() << ", " << v.y() << ")\n";
                diff_log << "  B vertices:\n";
                for (const auto& v : B) diff_log << "    (" << v.x() << ", " << v.y() << ")\n";
            }
        }
    }

    std::cout << "Trials: " << N << "\n";
    std::cout << "Same: " << same << "\n";
    std::cout << "Different: " << diff << "\n";
    std::cout << "Empty A: " << empty_a << ", Empty B: " << empty_b << "\n";
    std::cout << "Mean |area_A - area_B|: " << (total_area_diff / N) << "\n";
    std::cout << "Diffs logged to intersect_diff.txt\n";
    return 0;
}

