#ifndef GEOMETRY_H
#define GEOMETRY_H

// =============================================================================
//  Geometry primitives and intersection algorithms
//
//  Lifted out of simplify.cpp to keep the algorithm flow readable.  Each
//  helper is documented where it is defined (geometry.cpp); this header
//  only carries declarations and the CGAL kernel aliases that simplify.cpp
//  and the rest of the code base use.
// =============================================================================

#include <CGAL/Cartesian_converter.h>
#include <CGAL/Exact_predicates_inexact_constructions_kernel.h>
#include <CGAL/Exact_predicates_exact_constructions_kernel.h>
#include <CGAL/Polygon_2.h>
#include <CGAL/Polygon_with_holes_2.h>
#include <CGAL/intersections.h>

#include <optional>
#include <vector>

// -----------------------------------------------------------------------------
//  CGAL kernel aliases.  All of simplify.cpp / drawing.h operate on these.
// -----------------------------------------------------------------------------

using Epick = CGAL::Exact_predicates_inexact_constructions_kernel;
using Epeck = CGAL::Exact_predicates_exact_constructions_kernel;

// Convert Epick <-> Epeck for the intersection construction functions.
// Defined inline so each translation unit gets its own instance (avoids ODR).
static inline CGAL::Cartesian_converter<Epick, Epeck> conv_to_exact;
static inline CGAL::Cartesian_converter<Epeck, Epick> conv_to_inexact;

using Kernel  = Epick;
using Point   = Kernel::Point_2;
using Vector  = Kernel::Vector_2;
using Segment = Kernel::Segment_2;
using Ray     = Kernel::Ray_2;
using Line    = Kernel::Line_2;
using Bbox    = CGAL::Bbox_2;
using Rect    = CGAL::Iso_rectangle_2<Kernel>;

using Polygon           = CGAL::Polygon_2<Kernel>;
using Polygon_with_holes = CGAL::Polygon_with_holes_2<Kernel>;

// -----------------------------------------------------------------------------
//  IntersectKernel — a non-Epick kernel used internally by the boundary-point
//  + convex_hull algorithm (intersect_convex_polygons).  The conversions
//  to/from Epick are deliberately simple (to_double / static_cast<double>)
//  because the input coordinates are already doubles in [0, 3000].  See
//  geometry.cpp for the rationale.
// -----------------------------------------------------------------------------

using IntersectKernel  = CGAL::Simple_cartesian<double>;
using IntersectPoint   = IntersectKernel::Point_2;
using IntersectSegment = IntersectKernel::Segment_2;
using IntersectPolygon = CGAL::Polygon_2<IntersectKernel>;

// -----------------------------------------------------------------------------
//  Helpers
// -----------------------------------------------------------------------------

// Signed polygon area in doubles (half of the cross-product sum).  Exact for
// Epick since the cross product of two doubles is exact.
double kernel_signed_area(const std::vector<Point>& P);

// Epick -> IntersectKernel conversion (lossy to_double round-trip).
IntersectPoint to_intersect(const Point& p);
Point          from_intersect(const IntersectPoint& p);

// Point-in-convex-polygon test on IntersectKernel (assumes CCW).
bool point_in_polygon(const IntersectPoint& p,
                      const std::vector<IntersectPoint>& poly);

// Segment-segment intersection on IntersectKernel.  Returns nullopt when
// the segments are parallel or disjoint.
std::optional<IntersectPoint> segment_intersection(
    const IntersectPoint& p1, const IntersectPoint& p2,
    const IntersectPoint& q1, const IntersectPoint& q2);

// Point-in-convex-polygon test on Epick (assumes CCW).  Epick's orientation
// predicate is exact in sign.
bool point_in_convex_poly(const Point& p, const std::vector<Point>& poly);

// True iff every vertex of `inner` lies inside `outer` (both CCW convex).
bool all_points_in_convex_poly(const std::vector<Point>& inner,
                               const std::vector<Point>& outer);

// Infinite-line intersection of the half-plane edge (a, b) with the subject
// segment (p1, p2).  Computed in Epeck so the result lies on the exact line.
std::optional<Point> line_intersect(const Point& a, const Point& b,
                                    const Point& p1, const Point& p2);

// Sutherland-Hodgman half-plane clip.  `subject` is CCW; the kept half-plane
// is orientation(a, b, .) != RIGHT_TURN.
std::vector<Point> clip_halfplane(const std::vector<Point>& subject,
                                  const Point& a, const Point& b);

// Boundary-points + convex hull.  Collects every polygon vertex and segment
// intersection, deduplicates, then runs CGAL::convex_hull_2.
std::vector<Point> intersect_convex_polygons(const std::vector<Point>& lhs,
                                             const std::vector<Point>& rhs);

// Sutherland-Hodgman convex-convex intersection.  O(|P| * |Q|) orientation
// tests, no allocations beyond the output.  Assumes CCW inputs.
std::vector<Point> convex_intersect_fast(const std::vector<Point>& Pin,
                                         const std::vector<Point>& Qin);

#endif // GEOMETRY_H

// =============================================================================
//  Geometry primitives and intersection algorithms
//
//  See geometry.h for declarations and the overall design rationale.
// =============================================================================

#include "geometry.h"
#include "timer.h"

#include <CGAL/Boolean_set_operations_2.h>
#include <CGAL/convex_hull_2.h>

#include <algorithm>
#include <utility>

// =============================================================================
//  IntersectKernel conversion helpers
// =============================================================================

IntersectPoint to_intersect(const Point& p) {
    return IntersectPoint(CGAL::to_double(p.x()), CGAL::to_double(p.y()));
}

Point from_intersect(const IntersectPoint& p) {
    return Point(static_cast<double>(p.x()), static_cast<double>(p.y()));
}

// =============================================================================
//  Polygon area and point-in-polygon tests
// =============================================================================

double kernel_signed_area(const std::vector<Point>& P) {
    double s = 0.0;
    int sz = (int)P.size();
    for (int i = 0; i < sz; ++i) {
        const Point& a = P[i];
        const Point& b = P[(i + 1) % sz];
        s += CGAL::to_double(a.x() * b.y() - b.x() * a.y());
    }
    return s / 2.0;
}

// IntersectKernel variant used by intersect_convex_polygons (assumes CCW).
bool point_in_polygon(const IntersectPoint& p,
                      const std::vector<IntersectPoint>& poly) {
    int n = (int)poly.size();
    for (int i = 0; i < n; i++) {
        const IntersectPoint& a = poly[i];
        const IntersectPoint& b = poly[(i + 1) % n];
        if (!CGAL::left_turn(a, b, p)) return false;
    }
    return true;
}

// =============================================================================
//  Segment-segment intersection (IntersectKernel)
// =============================================================================

std::optional<IntersectPoint> segment_intersection(
    const IntersectPoint& p1, const IntersectPoint& p2,
    const IntersectPoint& q1, const IntersectPoint& q2) {
    auto inter = CGAL::intersection(IntersectSegment(p1, p2),
                                    IntersectSegment(q1, q2));
    if (inter && std::holds_alternative<IntersectPoint>(*inter)) {
        return std::get<IntersectPoint>(*inter);
    }
    return std::nullopt;
}

// =============================================================================
//  Boundary-points + convex_hull convex-convex intersection
// =============================================================================

// Collects all boundary points and segment intersections, deduplicates by
// (x, y), then computes CGAL::convex_hull_2.  Heavy use of TIMER blocks
// because the algorithm has 6 distinct sub-stages that callers profile.
std::vector<Point> intersect_convex_polygons(const std::vector<Point>& lhs,
                                             const std::vector<Point>& rhs) {
    std::vector<IntersectPoint> P_verts, Q_verts;
    {
        TIMER("conv_convert");
        P_verts.reserve(lhs.size());
        Q_verts.reserve(rhs.size());
        for (const auto& p : lhs) P_verts.push_back(to_intersect(p));
        for (const auto& p : rhs) Q_verts.push_back(to_intersect(p));
    }

    if (P_verts.size() < 3 || Q_verts.size() < 3) return {};

    int n = (int)P_verts.size();
    int m = (int)Q_verts.size();

    std::vector<std::pair<std::pair<double,double>, IntersectPoint>> pairs;
    pairs.reserve(n + m + n * m);

    {
        TIMER("pip_tests");
        auto add_point = [&](const IntersectPoint& p) {
            double x = CGAL::to_double(p.x());
            double y = CGAL::to_double(p.y());
            pairs.emplace_back(std::make_pair(x, y), p);
        };

        // Containment shortcuts: if every P-vertex lies inside Q, then
        // P ⊆ Q and the intersection is exactly P.  When triggered we
        // skip the O(n·m) seg_intersections sweep entirely.
        bool all_p_in_q = (n > 0);
        for (int i = 0; i < n; i++) {
            if (point_in_polygon(P_verts[i], Q_verts)) {
                add_point(P_verts[i]);
            } else {
                all_p_in_q = false;
            }
        }
        // Symmetric: if every Q-vertex lies inside P, then Q ⊆ P and the
        // intersection is exactly Q.  This subsumes the all_p_in_q case
        // when both polygons are identical.
        bool all_q_in_p = (m > 0);
        for (int j = 0; j < m; j++) {
            if (point_in_polygon(Q_verts[j], P_verts)) {
                add_point(Q_verts[j]);
            } else {
                all_q_in_p = false;
            }
        }
        if (all_q_in_p) goto dedup_and_hull;
        if (all_p_in_q) goto dedup_and_hull;
    }

    {
        TIMER("seg_intersections");
        // Precompute segment bboxes so we can early-exit non-overlapping
        // (i, j) pairs.  CGAL's segment_intersection runs exact predicates
        // (orientation + between tests), which are far more expensive than
        // a few double comparisons.  For our typical n, m ≈ 6 this trims
        // ~30-50% of the inner iterations.
        std::vector<CGAL::Bbox_2> p_bbox(n), q_bbox(m);
        for (int i = 0; i < n; i++) {
            const IntersectPoint& a = P_verts[i];
            const IntersectPoint& b = P_verts[(i + 1) % n];
            p_bbox[i] = CGAL::Bbox_2(
                std::min(a.x(), b.x()), std::min(a.y(), b.y()),
                std::max(a.x(), b.x()), std::max(a.y(), b.y()));
        }
        for (int j = 0; j < m; j++) {
            const IntersectPoint& a = Q_verts[j];
            const IntersectPoint& b = Q_verts[(i + 1) % m];
            q_bbox[j] = CGAL::Bbox_2(
                std::min(a.x(), b.x()), std::min(a.y(), b.y()),
                std::max(a.x(), b.x()), std::max(a.y(), b.y()));
        }
        for (int i = 0; i < n; i++) {
            const IntersectPoint& p1 = P_verts[i];
            const IntersectPoint& p2 = P_verts[(i + 1) % n];
            const CGAL::Bbox_2& pb = p_bbox[i];
            for (int j = 0; j < m; j++) {
                const CGAL::Bbox_2& qb = q_bbox[j];
                if (pb.xmax() < qb.xmin() || pb.xmin() > qb.xmax() ||
                    pb.ymax() < qb.ymin() || pb.ymin() > qb.ymax()) {
                    continue;
                }
                const IntersectPoint& q1 = Q_verts[j];
                const IntersectPoint& q2 = Q_verts[(j + 1) % m];
                auto inter = segment_intersection(p1, p2, q1, q2);
                if (inter) {
                    double x = CGAL::to_double(inter->x());
                    double y = CGAL::to_double(inter->y());
