// =============================================================================
//  Sutherland-Hodgman helpers (Epick + Epeck where needed)
// =============================================================================

bool point_in_convex_poly(const Point& p, const std::vector<Point>& poly) {
    int n = (int)poly.size();
    for (int i = 0; i < n; ++i) {
        const Point& a = poly[i];
        const Point& b = poly[(i + 1) % n];
        if (CGAL::orientation(a, b, p) == CGAL::RIGHT_TURN) return false;
    }
    return true;
}

bool all_points_in_convex_poly(const std::vector<Point>& inner,
                               const std::vector<Point>& outer) {
    for (const auto& v : inner) {
        if (!point_in_convex_poly(v, outer)) return false;
    }
    return true;
}

// Line-line intersection for the half-plane clipper.  Given a directed edge
// (a, b) defining the "inside" half-plane (a point q is inside iff
// orientation(a, b, q) != RIGHT_TURN) and a directed input segment (p1, p2),
// return the intersection point of the two lines, or std::nullopt if the
// segments don't intersect (parallel/collinear case).
std::optional<Point> line_intersect(const Point& a, const Point& b,
                                    const Point& p1, const Point& p2) {
    // Guard against degenerate inputs.  If a polygon vertex was itself
    // produced by a prior intersection and rounds to the same coordinates
    // as its neighbour, we have a zero-length segment here.  A clip edge of
    // zero length can't define a half-plane, so we keep the inside endpoint.
    if (p1.x() == p2.x() && p1.y() == p2.y()) return p1;
    if (a.x() == b.x() && a.y() == b.y()) {
        // Clip edge is degenerate; keep the segment endpoint inside the half-plane.
        return (CGAL::orientation(a, b, p1) != CGAL::RIGHT_TURN)
                   ? std::optional<Point>(p1) : std::nullopt;
    }

    // Compute the line-line intersection in Epeck (exact) so the result is
    // exactly on the two infinite lines, which is what Sutherland-Hodgman
    // requires.  Using segments here is wrong: the clip edge is an infinite
    // line defining a half-plane, not a finite segment.
    Epeck::Point_2 ae  = conv_to_exact(a);
    Epeck::Point_2 be  = conv_to_exact(b);
    Epeck::Point_2 p1e = conv_to_exact(p1);
    Epeck::Point_2 p2e = conv_to_exact(p2);

    // The clip edge defines a half-plane bounded by an INFINITE line, not a
    // segment.  We must intersect with that line, not the finite segment
    // (a, b) — using Segment_2 here causes line_intersect to return nullopt
    // whenever the subject edge crosses the line outside [a, b], which then
    // drops the intersection vertex from the clipped polygon and corrupts
    // the intersection result.
    Epeck::Line_2 line_ab(ae, be);
    Epeck::Line_2 line_p(p1e, p2e);
    auto inter = CGAL::intersection(line_ab, line_p);
    if (!inter) return std::nullopt;        // parallel or coincident lines
    if (const Epeck::Point_2* ip = std::get_if<Epeck::Point_2>(&*inter)) {
        return conv_to_inexact(*ip);
    }
    return std::nullopt;                    // coincident lines
}

// Sutherland-Hodgman half-plane clip.  `subject` is a CCW convex polygon;
// the half-plane is defined by directed edge (a, b) with the inside being
// the LEFT side (i.e. orientation(a, b, p) != RIGHT_TURN).
//
// Used by convex_intersect_fast: for each edge of the `clip` polygon we
// clip the running subject against that half-plane.  After |clip| edges
// the running subject is exactly `subject ∩ clip`.
std::vector<Point> clip_halfplane(const std::vector<Point>& subject,
                                  const Point& a, const Point& b) {
    int n = (int)subject.size();
    if (n == 0) return {};

    // Convert clip edge to Epeck for exact orientation tests.  Epick
    // (floating-point) orientation can misclassify near-parallel edges due
    // to rounding, causing clip_halfplane to call line_intersect on
    // segments that don't actually cross the half-plane boundary.
    // line_intersect then returns null, and we append a bogus vertex that
    // corrupts the polygon geometry.
    Epeck::Point_2 ae = conv_to_exact(a);
    Epeck::Point_2 be = conv_to_exact(b);

    std::vector<Point> out;
    out.reserve(n + 1);

    for (int i = 0; i < n; ++i) {
        const Point& cur  = subject[i];
        const Point& prev = subject[(i + n - 1) % n];
        auto o_cur  = CGAL::orientation(ae, be, conv_to_exact(cur));
        auto o_prev = CGAL::orientation(ae, be, conv_to_exact(prev));
        bool cur_in  = (o_cur  != CGAL::RIGHT_TURN);
        bool prev_in = (o_prev != CGAL::RIGHT_TURN);

        if (cur_in) {
            if (!prev_in) {
                if (auto ip = line_intersect(a, b, prev, cur)) out.push_back(*ip);
            }
            out.push_back(cur);
        } else if (prev_in) {
            if (auto ip = line_intersect(a, b, prev, cur)) out.push_back(*ip);
        }
    }
    return out;
}

// =============================================================================
//  Sutherland-Hodgman convex-convex intersection (top-level)
// =============================================================================

std::vector<Point> convex_intersect_fast(const std::vector<Point>& Pin,
                                         const std::vector<Point>& Qin) {
    if (Pin.size() < 3 || Qin.size() < 3) return {};

    // Normalise both to CCW using exact (Epeck) signed area.  The previous
    // Epick (floating-point) kernel_signed_area could misclassify nearly-
    // zero-area polygons, reversing one of them and corrupting the
    // intersection.
    auto signed_area_sign = [](const std::vector<Point>& P) {
        Epeck::FT s = 0;
        int sz = (int)P.size();
        for (int i = 0; i < sz; ++i) {
            Epeck::Point_2 a = conv_to_exact(P[i]);
            Epeck::Point_2 b = conv_to_exact(P[(i + 1) % sz]);
            s += a.x() * b.y() - b.x() * a.y();
        }
        return CGAL::sign(s);
    };

    std::vector<Point> P, Q;
    P.reserve(Pin.size());
    Q.reserve(Qin.size());
    if (signed_area_sign(Pin) < 0) { P.assign(Pin.rbegin(), Pin.rend()); }
    else                            { P = Pin; }
    if (signed_area_sign(Qin) < 0) { Q.assign(Qin.rbegin(), Qin.rend()); }
    else                            { Q = Qin; }

    // Containment shortcuts: if one polygon is entirely inside the other,
    // return the inner one.  We test P[0] inside Q (and vice versa), then
    // validate that ALL vertices of the inner polygon are inside the outer
    // one — a single false positive (e.g. a shared boundary vertex
    // misclassified) would silently return the wrong polygon and corrupt
    // the Fréchet bound.
    if (point_in_convex_poly(P[0], Q) && all_points_in_convex_poly(P, Q)) return P;
    if (point_in_convex_poly(Q[0], P) && all_points_in_convex_poly(Q, P)) return Q;

    // Otherwise clip P against each edge of Q.
    std::vector<Point> running = P;
    int m = (int)Q.size();
    for (int i = 0; i < m; ++i) {
        const Point& a = Q[i];
        const Point& b = Q[(i + 1) % m];
        running = clip_halfplane(running, a, b);
        if (running.size() < 3) return {};   // intersection empty
    }
    return running;
}

