    // mathematically on the disk edge may round to slightly > r^2, so we
    // accept corners up to r^2 + r*1e-3 (well below one grid spacing).
    const double r = R_val();
    const double r2_tol = r * r + r * 1e-3;
    const int i_min = static_cast<int>(-r / GRID) - 1;
    const int i_max = -i_min;
    const int j_min = i_min;
    const int j_max = i_max;
