        const Point& a = P[i];
        const Point& b = P[(i + 1) % sz];
        s += CGAL::to_double(a.x() * b.y() - b.x() * a.y());
    }
    return s / 2.0;
}

// Using Simple_cartesian<double> for intersection: fast but no robustness guarantees
// on near-degenerate inputs. For the well-conditioned integer-coordinate inputs
// in [0,3000] used by this application, this is sufficient.
using IntersectKernel = CGAL::Simple_cartesian<double>;
using IntersectPoint = IntersectKernel::Point_2;
using IntersectSegment = IntersectKernel::Segment_2;
using IntersectPolygon = CGAL::Polygon_2<IntersectKernel>;

// Helper to convert from Kernel::Point_2 to IntersectPoint
static IntersectPoint to_intersect(const Point& p) {
    return IntersectPoint(CGAL::to_double(p.x()), CGAL::to_double(p.y()));
}

// Helper to convert from IntersectPoint back to Point
static Point from_intersect(const IntersectPoint& p) {
    return Point(static_cast<double>(p.x()), static_cast<double>(p.y()));
}

// Point-in-convex-polygon test using IntersectKernel
static bool point_in_polygon(const IntersectPoint& p, const std::vector<IntersectPoint>& poly) {
    int n = (int)poly.size();
    for (int i = 0; i < n; i++) {
        const IntersectPoint& a = poly[i];
        const IntersectPoint& b = poly[(i + 1) % n];
        if (!CGAL::left_turn(a, b, p)) {
            return false;
        }
    }
    return true;
}

// Segment-segment intersection using IntersectKernel
static std::optional<IntersectPoint> segment_intersection(const IntersectPoint& p1, const IntersectPoint& p2,
                                                          const IntersectPoint& q1, const IntersectPoint& q2) {
    auto inter = CGAL::intersection(IntersectSegment(p1, p2), IntersectSegment(q1, q2));
    if (inter && std::holds_alternative<IntersectPoint>(*inter)) {
        return std::get<IntersectPoint>(*inter);
    }
    return std::nullopt;
}

// Convex polygon intersection using boundary point collection + convex hull
// Collects all boundary points and intersection points, then computes convex hull.
static std::vector<Point> intersect_convex_polygons(const std::vector<Point>& lhs,
                                                   const std::vector<Point>& rhs) {
    std::vector<IntersectPoint> P_verts, Q_verts;
    {
        TIMER("conv_convert");
        P_verts.reserve(lhs.size());
        Q_verts.reserve(rhs.size());
        for (const auto& p : lhs) P_verts.push_back(to_intersect(p));
        for (const auto& p : rhs) Q_verts.push_back(to_intersect(p));
    }

    if (P_verts.size() < 3 || Q_verts.size() < 3) return {};

    int n = (int)P_verts.size();
    int m = (int)Q_verts.size();

    // Collect (key, candidate) pairs then deduplicate via sort+unique.
    // Faster than std::set because: no tree allocations, better cache locality.
    std::vector<std::pair<std::pair<double,double>, IntersectPoint>> pairs;
    pairs.reserve(n + m + n * m);

    {
        TIMER("pip_tests");
        auto add_point = [&](const IntersectPoint& p) {
            double x = CGAL::to_double(p.x());
            double y = CGAL::to_double(p.y());
            pairs.emplace_back(std::make_pair(x, y), p);
        };

        for (int i = 0; i < n; i++) {
            if (point_in_polygon(P_verts[i], Q_verts)) add_point(P_verts[i]);
        }
        for (int j = 0; j < m; j++) {
            if (point_in_polygon(Q_verts[j], P_verts)) add_point(Q_verts[j]);
        }
    }

    {
        TIMER("seg_intersections");
        for (int i = 0; i < n; i++) {
            const IntersectPoint& p1 = P_verts[i];
            const IntersectPoint& p2 = P_verts[(i + 1) % n];
            for (int j = 0; j < m; j++) {
                const IntersectPoint& q1 = Q_verts[j];
                const IntersectPoint& q2 = Q_verts[(j + 1) % m];
                auto inter = segment_intersection(p1, p2, q1, q2);
                if (inter) {
                    double x = CGAL::to_double(inter->x());
                    double y = CGAL::to_double(inter->y());
                    pairs.emplace_back(std::make_pair(x, y), *inter);
                }
            }
        }
    }

    if (pairs.empty()) return {};

    std::vector<IntersectPoint> candidates;
    {
        TIMER("sort_dedup");
        // Sort by key and deduplicate
        std::sort(pairs.begin(), pairs.end(),
                  [](const auto& a, const auto& b) {
                      if (a.first.first != b.first.first) return a.first.first < b.first.first;
                      return a.first.second < b.first.second;
                  });

        candidates.reserve(pairs.size());
        candidates.push_back(pairs[0].second);
        for (size_t i = 1; i < pairs.size(); i++) {
            if (pairs[i].first != pairs[i-1].first) {
                candidates.push_back(pairs[i].second);
            }
        }
    }

    if (candidates.size() < 3) return {};

    std::vector<IntersectPoint> hull;
    {
        TIMER("convex_hull");
        CGAL::convex_hull_2(candidates.begin(), candidates.end(), std::back_inserter(hull));
    }

    if (hull.size() < 3) return {};

    std::vector<Point> result;
    {
        TIMER("result_convert");
        result.reserve(hull.size());
        for (const auto& hp : hull) {
            result.push_back(from_intersect(hp));
        }
    }
    return result;
}

