double expected_frechet = 0;

std::vector<Point> get_points_from_grid(const Point &p) {
    const double px = CGAL::to_double(p.x());
    const double py = CGAL::to_double(p.y());
    const double GRID = GRID_val();
    if (DELTA == 0) {
        return std::vector<Point>{p};
    }
    // Cell-based candidate generation: the simplify algorithm approximates
    // each ball of radius r = (1 + EPSILON/2) * DELTA by the union of grid
    // cells it intersects, and the candidate set is every corner of every
    // stabbed cell.  This guarantees the on-grid Frechet reaches the
    // intended bound (1 + EPSILON/2) * DELTA — a strictly-corner-only
    // walk like for_each_grid_row stops short of that.
    //
    // A cell (x_cell, y_cell) is stabbed when at least one of its four
    // corners (x_cell*, y_cell*) ∈ {(x_cell,y_cell),(x_cell+1,y_cell),
    // (x_cell,y_cell+1),(x_cell+1,y_cell+1)} lies inside the disk.  Both
    // row indices y_cell and y_cell+1 are candidates, so for each row we
    // compute the corner-x range and the cell range is the union over the
    // bottom row and the row above.
    //
    // Each cell contributes its 4 corner indices to a flat vector (with
    // up to 4× duplicates between neighbouring cells).  Sort+unique keeps
    // the per-cell cost tight and avoids the per-corner unordered_set
    // overhead.  Total candidate count is comparable to the corner-only
    // walk plus a one-grid-cell-thick outer annulus, so the runtime stays
    // under a second on the test cases.
    const double r = R_val();
    const double r2 = r * r;
    const int y_min = static_cast<int>(-r / GRID) - 1;
    const int y_max = -y_min;
    auto key = [](int ix, int iy) -> uint64_t {
        return (static_cast<uint64_t>(static_cast<int32_t>(ix)) << 32) |
               static_cast<uint32_t>(static_cast<int32_t>(iy));
    };
    std::vector<uint64_t> keys;
    keys.reserve(512);
    for (int y = y_min; y <= y_max; ++y) {
        const double y_actual = y * GRID;
        const double dy2 = y_actual * y_actual;
        if (dy2 > r2) continue;  // both row y and row y+1 outside the disk
        // dx is the disk's x-extrent on row y.  Corners at integer x
        // indices with |x| * GRID <= dx are inside the disk (with the
        // negative-side slack matching for_each_grid_row above).
        const double dx = std::sqrt(r2 - dy2);
        const int x_min_corner = static_cast<int>(-dx / GRID - 1);
        const int x_max_corner = static_cast<int>(+dx / GRID + 1);
        // Cells stabbed from the bottom edge (row y) lie at column
        // indices in [x_min_corner - 1, x_max_corner] — a corner at x_cell
        // or x_cell+1 must hit row y's corner range.
        int cell_min = x_min_corner - 1;
        int cell_max = x_max_corner;
        // If row y+1 also intersects the disk, expand to include cells
        // stabbed only from the top edge.
        const double y1_actual = (y + 1) * GRID;
        const double dy1_2 = y1_actual * y1_actual;
        if (dy1_2 <= r2) {
            const double dx1 = std::sqrt(r2 - dy1_2);
            const int x_min_top = static_cast<int>(-dx1 / GRID - 1);
            const int x_max_top = static_cast<int>(+dx1 / GRID + 1);
            cell_min = std::min(cell_min, x_min_top - 1);
            cell_max = std::max(cell_max, x_max_top);
        }
        for (int x_cell = cell_min; x_cell <= cell_max; ++x_cell) {
            const int xl = x_cell, yl = y, xh = x_cell + 1, yh = y + 1;
            keys.push_back(key(xl, yl));
            keys.push_back(key(xh, yl));
            keys.push_back(key(xl, yh));
            keys.push_back(key(xh, yh));
        }
    }
    std::sort(keys.begin(), keys.end());
    keys.erase(std::unique(keys.begin(), keys.end()), keys.end());

    std::vector<Point> points;
    points.reserve(keys.size());
    for (uint64_t k : keys) {
        const int ix = static_cast<int32_t>(k >> 32);
        const int iy = static_cast<int32_t>(k & 0xffffffffu);
        const Point pt(px + ix * GRID, py + iy * GRID);
        points.push_back(pt);
        expected_frechet = std::max(expected_frechet,
            CGAL::to_double(CGAL::squared_distance(p, pt)));
    }
    return points;
}

