double expected_frechet = 0;

std::vector<Point> get_points_from_grid(const Point &p) {
    const double px = CGAL::to_double(p.x());
    const double py = CGAL::to_double(p.y());
    const double GRID = GRID_val();
    if (DELTA == 0) {
        return std::vector<Point>{p};
    }
    // Cell-based candidate generation: the simplify algorithm approximates
    // each ball of radius r = (1 + EPSILON/2) * DELTA by the union of grid
    // cells it intersects, and every corner of every such cell is a
    // candidate vertex.  Emitting all four corners — even ones strictly
    // outside the disk — is what lets the algorithm reach the Fréchet
    // bound (1 + EPSILON) * DELTA on this benchmark.
    //
    // A cell C = [x*GRID, (x+1)*GRID] x [y*GRID, (y+1)*GRID] intersects
    // the disk iff the closest point of C to p is within r.  With p at
    // the origin, that distance is
    //   d^2 = (max(0, x, -x-1) * GRID)^2 + (max(0, y, -y-1) * GRID)^2
    // (the "clamp to cell" of origin's coordinates, in GRID units).
    // Substituting k_x = max(0, x, -x-1) and k_y = max(0, y, -y-1),
    // a cell is stabbed iff k_x^2 + k_y^2 <= (r/GRID)^2.
    //
    // We iterate (k_x, k_y) over the disk in (k_x, k_y) space and emit
    // all 4 cells at (k_x, k_y) -> {x=k_x or x=-k_x-1} x {y=k_y or y=-k_y-1}.
    // This is O((r/GRID)^2) cells, ~289 for the test case.  Each cell
    // pushes 4 corner indices to a flat vector with up to 4x duplicates
    // at shared boundaries; sort+unique cleans up before point construction.
    const double r = R_val();
    const double r_over_grid = r / GRID;
    const int K_max = static_cast<int>(r_over_grid) + 2;  // +2 for FP slack
    const double r2_units = r_over_grid * r_over_grid;    // r^2 / GRID^2
    auto key = [](int ix, int iy) -> uint64_t {
        return (static_cast<uint64_t>(static_cast<int32_t>(ix)) << 32) |
               static_cast<uint32_t>(static_cast<int32_t>(iy));
    };
    std::vector<uint64_t> keys;
    keys.reserve(1024);
    for (int ky = 0; ky <= K_max; ++ky) {
        const double ky2 = static_cast<double>(ky) * ky;
        if (ky2 > r2_units + 1e-9) break;
        const double kx_max_sq = r2_units - ky2;
        const double kx_max_d = std::sqrt(std::max(0.0, kx_max_sq));
        const int kx_max = static_cast<int>(kx_max_d) + 1;
        for (int kx = 0; kx <= kx_max; ++kx) {
            if (static_cast<double>(kx) * kx + ky2 > r2_units + 1e-9) break;
            // Two cell columns for this kx: x = kx and x = -kx-1
            const int x_pos = kx;
            const int x_neg = -kx - 1;
            const int y_pos = ky;
            const int y_neg = -ky - 1;
            // Emit all four cell corners for each cell; handle the
            // special case kx=0 / ky=0 to avoid double-pushing at the
            // cell-pair axes.
            auto emit_cell = [&](int xc, int yc) {
                keys.push_back(key(xc,     yc));
                keys.push_back(key(xc + 1, yc));
                keys.push_back(key(xc,     yc + 1));
                keys.push_back(key(xc + 1, yc + 1));
            };
            if (ky == 0) {
                // Two cells share the y=0 boundary (one above, one below).
                emit_cell(x_pos,  0);
                emit_cell(x_neg,  0);
                // (ky=0, kx=0) -> x_pos=0, x_neg=-1, y_pos=0, y_neg=-1.
                // emit_cell(0, 0) covers cell (0, 0); emit_cell(-1, 0)
                // covers cell (-1, 0).  Both bottom and top corners of
                // each cell are pushed, so the row y=0 corner is
                // pushed twice — dedup handles it.
            } else {
                // Four cells: (+, +), (+, -), (-, +), (-, -)
                emit_cell(x_pos, y_pos);
                emit_cell(x_pos, y_neg);
                emit_cell(x_neg, y_pos);
                emit_cell(x_neg, y_neg);
            }
        }
    }
    std::sort(keys.begin(), keys.end());
    keys.erase(std::unique(keys.begin(), keys.end()), keys.end());

    std::vector<Point> points;
    points.reserve(keys.size());
    for (uint64_t k : keys) {
        const int ix = static_cast<int32_t>(k >> 32);
        const int iy = static_cast<int32_t>(k & 0xffffffffu);
        const Point pt(px + ix * GRID, py + iy * GRID);
        points.push_back(pt);
        expected_frechet = std::max(expected_frechet,
            CGAL::to_double(CGAL::squared_distance(p, pt)));
    }
    return points;
}

