// Compute every grid corner that can appear in the candidate set for p:
// all four corners of every cell intersecting the ball of radius
// r = (1 + EPSILON/2) * DELTA centered at p.  See the full derivation
// in get_points_from_grid below; this helper factors out the iteration
// so both get_points_from_grid (raw corners) and get_conv_from_grid
// (convex hull of corners) can use it without duplication.
static std::vector<std::pair<int, int>> corner_indices_near(const Point &p) {
    const double px = CGAL::to_double(p.x());
    const double py = CGAL::to_double(p.y());
    const double GRID = GRID_val();
    const double r = R_val();
    const double r_over_grid = r / GRID;
    const int K_max = static_cast<int>(r_over_grid) + 2;  // +2 for FP slack
    const double r2_units = r_over_grid * r_over_grid;    // r^2 / GRID^2
    std::vector<std::pair<int, int>> out;
    out.reserve(512);
    for (int ky = 0; ky <= K_max; ++ky) {
        const double ky2 = static_cast<double>(ky) * ky;
        if (ky2 > r2_units + 1e-9) break;
        const double kx_max_d = std::sqrt(std::max(0.0, r2_units - ky2));
        const int kx_max = static_cast<int>(kx_max_d) + 1;
        for (int kx = 0; kx <= kx_max; ++kx) {
            if (static_cast<double>(kx) * kx + ky2 > r2_units + 1e-9) break;
            // Four cells per (kx, ky) pair — see get_points_from_grid.
            const int x_pos = kx, x_neg = -kx - 1;
            const int y_pos = ky, y_neg = -ky - 1;
            out.emplace_back(x_pos, y_pos);
            out.emplace_back(x_pos, y_neg);
            out.emplace_back(x_neg, y_pos);
            out.emplace_back(x_neg, y_neg);
        }
    }
    return out;
}

std::vector<Point> get_conv_from_grid(const Point &p) {
    const double px = CGAL::to_double(p.x());
    const double py = CGAL::to_double(p.y());
    const double GRID = GRID_val();
    auto cells = corner_indices_near(p);
    std::vector<Point> boundaries;
    boundaries.reserve(cells.size() * 4);
    for (const auto &[xc, yc] : cells) {
        boundaries.emplace_back(px + xc     * GRID, py + yc     * GRID);
        boundaries.emplace_back(px + (xc+1) * GRID, py + yc     * GRID);
        boundaries.emplace_back(px + xc     * GRID, py + (yc+1) * GRID);
        boundaries.emplace_back(px + (xc+1) * GRID, py + (yc+1) * GRID);
    }
    // Convex_hull_2 raises a precondition violation on degenerate inputs
    // (fewer than 3 distinct non-collinear points).  Return an empty polygon
    // in that case so the caller skips the empty intersection without
    // triggering the abort.
    if (boundaries.size() < 3) return {};
    std::vector<Point> conv;
    // O(n log n) hull; here h = O(n) so the asymptotic gain is modest.
    CGAL::convex_hull_2(boundaries.begin(), boundaries.end(),
                        std::back_inserter(conv));
    if (conv.size() < 3) return {};
    return conv;
}

