// All grid cells that intersect the disk of radius R_val() around p,
// expressed as cell coordinates (cells are unit squares in GRID-space).
// We iterate (kx, ky) over a quarter-disk in cell-distance coordinates
// and reflect into all four quadrants:
//   cell column x =  kx   or   -(kx + 1)
//   cell row    y =  ky   or   -(ky + 1)
// This is the same disk as the union over kx, ky with
//   (max(0, x, -x-1))^2 + (max(0, y, -y-1))^2 <= (R/GRID)^2
// but avoids scanning the full L-shaped region pointlessly.  Emitted
// cells are unique by construction (different (kx, ky) pairs and
// quadrant expansions never collide).
static std::vector<std::pair<int, int>> cells_near(const Point &p) {
    const double GRID = GRID_val();
    const double r2_units = (R_val() / GRID) * (R_val() / GRID);
    const int K_max = static_cast<int>(std::sqrt(r2_units)) + 2;  // FP slack
    std::vector<std::pair<int, int>> out;
    out.reserve(4 * (K_max + 1) * (K_max + 1));
    for (int ky = 0; ky <= K_max; ++ky) {
        const double ky2 = static_cast<double>(ky) * ky;
        if (ky2 > r2_units + 1e-9) break;
