    // around each stream point to be fully covered, so the convex hull of
    // the candidate corners must enclose the disk tightly.  Use the same
    // cell set that get_points_from_grid uses below.
    std::vector<Point> boundaries = points_from_cells(p, GRID_val(), cells_near(p));
