// Corners of the cells intersected by the disk of radius R centred at `p`.
// For each non-negative cell index (kx, ky) with kx² + ky² ≤ (R/GRID)², the
// cell closest to `p` is emitted as 4 corners.  The four corner offsets
// (xs, ys) ∈ {kx, -kx-1} × {ky, -ky-1} reflect the cell across the origin,
// so the union covers all four quadrants without an outer loop over cells.
static std::vector<Point> corners_near(const Point &p) {
    const double GRID   = GRID_val();
    const double r2_cell = (R_val() / GRID) * (R_val() / GRID);
    const int K_max = static_cast<int>(std::sqrt(r2_cell)) + 2;  // FP slack

    const double px = CGAL::to_double(p.x());
    const double py = CGAL::to_double(p.y());

    std::vector<Point> out;
    out.reserve(4 * (K_max + 1) * (K_max + 1));

    for (int ky = 0; ky <= K_max; ++ky) {
        const double ky2 = static_cast<double>(ky) * ky;
        if (ky2 > r2_cell + 1e-9) break;
        const int kx_max =
            static_cast<int>(std::sqrt(std::max(0.0, r2_cell - ky2))) + 1;
        for (int kx = 0; kx <= kx_max; ++kx) {
            if (static_cast<double>(kx) * kx + ky2 > r2_cell + 1e-9) break;
            // Cell index (kx, ky); its 4 reflected versions.
            for (int xs : {kx, -kx - 1})
                for (int ys : {ky, -ky - 1})
                    out.emplace_back(px + xs * GRID, py + ys * GRID);
        }
    }
    return out;
}

