// All candidate corners around `p`: the 4 corners of every cell whose
// closest point to `p` lies within R = (1 + EPSILON/2) * DELTA.  The cell
// C = [x, x+1] × [y, y+1] (in GRID units relative to p) is stabbed by the
// disk iff (max(0, x, -x-1))² + (max(0, y, -y-1))² ≤ (R/GRID)².  The
// transformation (k_x, k_y) = (max(0, x, -x-1), max(0, y, -y-1)) maps the
// disk-membership test onto a quarter-disk in k-space, and the inverse
// x ∈ {k_x, -k_x-1}, y ∈ {k_y, -k_y-1} reflects back to all four
// quadrants.  Emitting all four corners of each reflected cell matches
// the disk-clipping region exactly, so the convex hull of these points
// covers the full disk (used by get_conv_from_grid).
static std::vector<Point> corners_near(const Point &p) {
    const double GRID   = GRID_val();
    const double r2_cell = (R_val() / GRID) * (R_val() / GRID);
    const int K_max = static_cast<int>(std::sqrt(r2_cell)) + 2;  // FP slack

    const double px = CGAL::to_double(p.x());
    const double py = CGAL::to_double(p.y());

    std::vector<Point> out;
    out.reserve(4 * (K_max + 1) * (K_max + 1) * 4);

    for (int ky = 0; ky <= K_max; ++ky) {
        const double ky2 = static_cast<double>(ky) * ky;
        if (ky2 > r2_cell + 1e-9) break;
        const int kx_max =
            static_cast<int>(std::sqrt(std::max(0.0, r2_cell - ky2))) + 1;
        for (int kx = 0; kx <= kx_max; ++kx) {
            if (static_cast<double>(kx) * kx + ky2 > r2_cell + 1e-9) break;
            // Reflect the cell index (kx, ky) into all four quadrants and
            // emit every corner of each reflected cell.
            for (int xs : {kx, -kx - 1})
                for (int ys : {ky, -ky - 1})
                    for (int dx : {0, 1})
                        for (int dy : {0, 1})
                            out.emplace_back(px + (xs + dx) * GRID,
                                             py + (ys + dy) * GRID);
        }
    }
    return out;
}

std::vector<Point> get_conv_from_grid(const Point &p) {
    // The simplifier needs the disk of radius r = (1 + EPSILON/2) * DELTA
    // around each stream point to be fully covered, so the convex hull of
    // the candidate corners must enclose the disk tightly.  CGAL's hull
    // tolerates duplicate points, so we can hand it the un-deduped set.
    std::vector<Point> boundaries = corners_near(p);
    // Convex_hull_2 raises a precondition violation on degenerate inputs
    // (fewer than 3 distinct non-collinear points).  Return an empty polygon
    // in that case so the caller skips the empty intersection without
    // triggering the abort.
    if (boundaries.size() < 3) return {};
    std::vector<Point> conv;
    CGAL::convex_hull_2(boundaries.begin(), boundaries.end(),
                        std::back_inserter(conv));
    if (conv.size() < 3) return {};
    return conv;
}

double expected_frechet = 0;

std::vector<Point> get_points_from_grid(const Point &p) {
    if (DELTA == 0) return std::vector<Point>{p};

    // Cell-based candidate generation: the simplifier approximates the
    // ball of radius r = (1 + EPSILON/2) * DELTA around p by the union of
    // grid cells it intersects, and every corner of every such cell is a
    // candidate vertex.  Emitting all four corners — even ones strictly
    // outside the disk — is what lets the algorithm reach the Fréchet
    // bound (1 + EPSILON) * DELTA on this benchmark.
    std::vector<Point> corners = corners_near(p);
    // Adjacent cells share corners, so we get up to 4x duplicates before
    // dedup.  Dedup keeps `expected_frechet` accurate (otherwise
    // squared_distance would be over-counted for shared corners).
    std::sort(corners.begin(), corners.end(),
              [](const Point& a, const Point& b) {
                  return std::tie(a.x(), a.y()) < std::tie(b.x(), b.y());
              });
    corners.erase(std::unique(corners.begin(), corners.end()), corners.end());

    std::vector<Point> points;
    points.reserve(corners.size());
    for (const Point& pt : corners) {
        points.push_back(pt);
        expected_frechet = std::max(expected_frechet,
            CGAL::to_double(CGAL::squared_distance(p, pt)));
    }
    return points;
}

