#include "geometry.h"
#include <iostream>
#include <iomanip>
#include <vector>

using std::cout;
using std::vector;

static void dump(const vector<Point>& P, const char* tag) {
    cout << tag << " (" << P.size() << " verts):";
    for (const auto& p : P) cout << " (" << CGAL::to_double(p.x()) << "," << CGAL::to_double(p.y()) << ")";
    cout << "\n";
}

static int test_case(const char* name, const vector<Point>& P, const vector<Point>& Q) {
    auto A = intersect_convex_polygons(P, Q);
    auto B = convex_intersect_fast(P, Q);
    cout << "==== " << name << " ====\n";
    dump(P, "P");
    dump(Q, "Q");
    dump(A, "A (boundary+hull)");
    dump(B, "B (S-H)");
    return 0;
}

int main() {
    {
        // Unit square [0,2]x[0,2] vs [1,3]x[1,3]
        vector<Point> P{Point(0,0), Point(2,0), Point(2,2), Point(0,2)};
        vector<Point> Q{Point(1,1), Point(3,1), Point(3,3), Point(1,3)};
        test_case("shifted square", P, Q);
    }
    {
        // Triangle vs triangle: overlap a corner.
        vector<Point> P{Point(0,0), Point(3,0), Point(0,3)};
        vector<Point> Q{Point(1,1), Point(4,1), Point(1,4)};
        test_case("triangles", P, Q);
    }
    {
        // Pentagon-ish (regular 5-gon around origin, vs another 5-gon offset)
        vector<Point> P{
            Point(1.0, 0.0),
            Point(0.309, 0.951),
            Point(-0.809, 0.588),
