// Line-line intersection for the half-plane clipper.  Given a directed edge
// (a, b) defining the "inside" half-plane (a point q is inside iff
// orientation(a, b, q) != RIGHT_TURN) and a directed input segment (p1, p2),
// return the intersection point of the two lines, or std::nullopt if the
// segments don't intersect (parallel/collinear case).
std::optional<Point> line_intersect(const Point& a, const Point& b,
                                    const Point& p1, const Point& p2) {
    // Guard against degenerate inputs.  If a polygon vertex was itself
    // produced by a prior intersection and rounds to the same coordinates
    // as its neighbour, we have a zero-length segment here.  A clip edge of
    // zero length can't define a half-plane, so we keep the inside endpoint.
    if (p1.x() == p2.x() && p1.y() == p2.y()) return p1;
    if (a.x() == b.x() && a.y() == b.y()) {
        // Clip edge is degenerate; keep the segment endpoint inside the half-plane.
        return (CGAL::orientation(a, b, p1) != CGAL::RIGHT_TURN)
                   ? std::optional<Point>(p1) : std::nullopt;
    }

    // The clip edge defines a half-plane bounded by an INFINITE line, not a
    // segment.  We must intersect with that line, not the finite segment
    // (a, b) — using Segment_2 here causes line_intersect to return nullopt
    // whenever the subject edge crosses the line outside [a, b], which then
    // drops the intersection vertex from the clipped polygon and corrupts
    // the intersection result.
    //
    // Epick's Line_2 intersection computes the result in double precision
    // (Epick = exact predicates, inexact constructions).  That's fine here:
    // orientation tests against the result are still exact in sign (the
    // predicate is what matters for half-plane classification), and any
    // small rounding in the intersection point is bounded by 1-2 ulps which
    // doesn't change the predicate's sign for non-degenerate inputs.
    Line line_ab(a, b);
    Line line_p(p1, p2);
    auto inter = CGAL::intersection(line_ab, line_p);
    if (!inter) return std::nullopt;        // parallel or coincident lines
    if (const Point* ip = std::get_if<Point>(&*inter)) {
        return *ip;
    }
    return std::nullopt;                    // coincident lines
}

