        return (CGAL::orientation(a, b, p1) != CGAL::RIGHT_TURN)
                   ? std::optional<Point>(p1) : std::nullopt;
    }

    // Compute the line-line intersection in Epeck (exact) so the result is
    // exactly on the two infinite lines, which is what Sutherland-Hodgman
    // requires.  Using segments here is wrong: the clip edge is an infinite
