// Sutherland-Hodgman half-plane clip.  `subject` is a CCW convex polygon;
// the half-plane is defined by directed edge (a, b) with the inside being
// the LEFT side (i.e. orientation(a, b, p) != RIGHT_TURN).
//
// Used by convex_intersect_fast: for each edge of the `clip` polygon we
// clip the running subject against that half-plane.  After |clip| edges
// the running subject is exactly `subject ∩ clip`.
//
// We use Epick (exact predicates, inexact constructions) for orientation
// tests.  Epick's orientation is exact in sign — it never misclassifies
// "inside" vs "outside" relative to the half-plane, even for nearly-
// parallel edges — so the previous concern about rounding-driven
// misclassification doesn't apply here.  Line intersections are computed
// in double precision via line_intersect; the resulting point is then
// fed back into Epick orientation tests, which are still exact.
std::vector<Point> clip_halfplane(const std::vector<Point>& subject,
                                  const Point& a, const Point& b) {
    int n = (int)subject.size();
    if (n == 0) return {};

    std::vector<Point> out;
    out.reserve(n + 1);

    auto o_prev = CGAL::orientation(a, b, subject[(n - 1) % n]);
    bool prev_in = (o_prev != CGAL::RIGHT_TURN);

    for (int i = 0; i < n; ++i) {
        const Point& cur  = subject[i];
        auto o_cur  = CGAL::orientation(a, b, cur);
        bool cur_in  = (o_cur != CGAL::RIGHT_TURN);

        if (cur_in) {
            if (!prev_in) {
                if (auto ip = line_intersect(a, b, subject[(i + n - 1) % n], cur))
                    out.push_back(*ip);
            }
            out.push_back(cur);
        } else if (prev_in) {
            if (auto ip = line_intersect(a, b, subject[(i + n - 1) % n], cur))
                out.push_back(*ip);
        }
        prev_in = cur_in;
    }
    return out;
}

