std::vector<Point> convex_intersect_fast(const std::vector<Point>& Pin,
                                         const std::vector<Point>& Qin) {
    if (Pin.size() < 3 || Qin.size() < 3) return {};

    // Normalise both to CCW.  Epick's orientation is exact in sign, so
    // a non-zero signed area is correctly classified as positive/negative.
    // For a near-degenerate polygon the area can round to zero and we'd
    // skip the reversal — that path is handled by the all-points-inside
    // shortcut below, which catches the "P == Q" case.
    std::vector<Point> P, Q;
    P.reserve(Pin.size());
    Q.reserve(Qin.size());
    if (CGAL::orientation(Pin[0], Pin[1], Pin[2]) == CGAL::RIGHT_TURN) {
        P.assign(Pin.rbegin(), Pin.rend());
    } else {
        P = Pin;
    }
    if (CGAL::orientation(Qin[0], Qin[1], Qin[2]) == CGAL::RIGHT_TURN) {
        Q.assign(Qin.rbegin(), Qin.rend());
    } else {
        Q = Qin;
    }

    // Containment shortcuts: if one polygon is entirely inside the other,
    // return the inner one.  We test P[0] inside Q (and vice versa), then
    // validate that ALL vertices of the inner polygon are inside the outer
    // one — a single false positive (e.g. a shared boundary vertex
    // misclassified) would silently return the wrong polygon and corrupt
    // the Fréchet bound.
    if (point_in_convex_poly(P[0], Q) && all_points_in_convex_poly(P, Q)) return P;
    if (point_in_convex_poly(Q[0], P) && all_points_in_convex_poly(Q, P)) return Q;

    // Otherwise clip P against each edge of Q.
    std::vector<Point> running = P;
    int m = (int)Q.size();
    for (int i = 0; i < m; ++i) {
        const Point& a = Q[i];
        const Point& b = Q[(i + 1) % m];
        running = clip_halfplane(running, a, b);
        if (running.size() < 3) return {};   // intersection empty
    }
    return running;
}

