static void intersect(const Polygon& subject, const Polygon& clip,
                        std::back_insert_iterator<std::vector<Polygon_with_holes>> result) {
    TIMER("copy_verts");
    std::vector<Point> P_verts(subject.vertices_begin(), subject.vertices_end());
    std::vector<Point> Q_verts(clip.vertices_begin(), clip.vertices_end());

    {
        TIMER("convex_intersect");
        auto verts = convex_intersect_fast(P_verts, Q_verts);
        if (verts.size() < 3) return;
        // Drop redundant collinear-on-edge vertices before constructing the
        // Polygon.  Sutherland-Hodgman can emit collinear vertices when a
        // P-vertex lies on a Q-edge, and these accumulate across iterations
        // of the simplifier cascade — each extra vertex becomes a candidate
        // for the next step, blowing up the simplified output.  convex_hull_2
        // strips them and gives the minimal vertex representation.
        {
            TIMER("convex_hull");
            std::vector<Point> hull;
            CGAL::convex_hull_2(verts.begin(), verts.end(),
                                std::back_inserter(hull));
            verts.swap(hull);
        }
        if (verts.size() < 3) return;
        Polygon inter_poly(verts.begin(), verts.end());
        if (!inter_poly.is_simple()) return;
        if (inter_poly.is_clockwise_oriented()) inter_poly.reverse_orientation();
        *result++ = Polygon_with_holes(inter_poly);
    }

