#include "geometry.h"
#include <iostream>
#include <vector>
#include <iomanip>
#include <random>

using std::cout;
using std::vector;

static std::mt19937 rng(42);

// Generate random convex polygon near origin
static vector<Point> random_convex(double r, int n) {
    std::uniform_real_distribution<double> dist(-r, r);
    vector<Point> pts;
    for (int i = 0; i < n * 4; i++) {
        pts.push_back(Point(dist(rng), dist(rng)));
    }
    vector<Point> hull;
    CGAL::convex_hull_2(pts.begin(), pts.end(), std::back_inserter(hull));
    if ((int)hull.size() > n) hull.resize(n);
    return hull;
}

static vector<Point> strip_collinear(const vector<Point>& verts) {
    const int n = (int)verts.size();
    if (n < 3) return verts;
    vector<Point> result = verts;
    bool changed = true;
    while (changed) {
        changed = false;
        vector<Point> stripped;
        const int m = (int)result.size();
        for (int i = 0; i < m; ++i) {
            const Point& a = result[(i - 1 + m) % m];
            const Point& b = result[i];
            const Point& c = result[(i + 1) % m];
            if (CGAL::orientation(a, b, c) != CGAL::COLLINEAR) {
                stripped.push_back(b);
            } else {
                changed = true;
            }
        }
        result.swap(stripped);
    }
    return result;
}

static void dump(const vector<Point>& P, const char* tag) {
    cout << tag << " (" << P.size() << " verts):";
    for (const auto& p : P) cout << " (" << std::fixed << std::setprecision(4) << CGAL::to_double(p.x()) << "," << CGAL::to_double(p.y()) << ")";
    cout << "\n";
}

int main() {
    int n_trials = 0, n_diff = 0;
    for (int trial = 0; trial < 200; trial++) {
        std::uniform_int_distribution<int> ndist(3, 15);
        auto P = random_convex(10, ndist(rng));
        auto Q = random_convex(10, ndist(rng));
        auto fast = convex_intersect_fast(P, Q);
        if (fast.size() < 3) continue;
        n_trials++;

        auto stripped = strip_collinear(fast);
        vector<Point> hull;
        CGAL::convex_hull_2(fast.begin(), fast.end(), std::back_inserter(hull));

        if (stripped.size() != hull.size()) {
            n_diff++;
            if (n_diff <= 5) {
                cout << "=== Trial " << trial << " (P=" << P.size() << " Q=" << Q.size() << ") ===\n";
                dump(P, "P");
                dump(Q, "Q");
                dump(fast, "fast");
                dump(stripped, "stripped");
                dump(hull, "hull");
            }
        }
    }
    cout << "\nTrials: " << n_trials << ", Differing: " << n_diff << "\n";
    return 0;
}

