    static int coords[] = {0, 1, 2, 3, 4};
    static int cx[] = {-2, -1, 0, 1, 2, 3, 4, 5};
    static int cy[] = {-2, -1, 0, 1, 2, 3, 4, 5};

    vector<Point> pts;
    for (int i = 0; i < n * 4; i++) {
        int xi = cx[rand() % 8];
        int yi = cy[rand() % 8];
        pts.push_back(Point(xi * GRID, yi * GRID));
    }
    vector<Point> hull;
    CGAL::convex_hull_2(pts.begin(), pts.end(), std::back_inserter(hull));
    if ((int)hull.size() > n) hull.resize(n);
    return hull;
}

static vector<Point> strip_collinear(const vector<Point>& verts) {
