static vector<Point> strip_collinear(const vector<Point>& verts) {
    const int n = (int)verts.size();
    if (n < 3) return verts;
    vector<Point> result = verts;
    bool changed = true;
    while (changed) {
        changed = false;
        vector<Point> stripped;
        const int m = (int)result.size();
        // First pass: drop exact duplicates of adjacent vertices.  For a
        // convex polygon, a duplicated point is a zero-length edge; we keep
        // exactly one copy as a real extreme-point vertex.
        for (int i = 0; i < m; ++i) {
            const Point& b = result[i];
            const Point& c = result[(i + 1) % m];
            if (b == c) {
                changed = true;
                // Skip the duplicate `c` by advancing i+1 in the next iteration.
                // Implementation: skip emitting b this round, and we'll merge.
                continue;
            }
            stripped.push_back(b);
        }
        // If we didn't see any duplicates, fall through to the collinear check.
        if (!changed) {
            stripped.clear();
            for (int i = 0; i < m; ++i) {
                const Point& a = result[(i - 1 + m) % m];
                const Point& b = result[i];
                const Point& c = result[(i + 1) % m];
                if (a == b || b == c) {
                    changed = true; // shouldn't happen if we just deduped
                    continue;
                }
                if (CGAL::orientation(a, b, c) != CGAL::COLLINEAR) {
                    stripped.push_back(b);
                } else {
                    changed = true;
                }
            }
        }
        result.swap(stripped);
        // Bail if polygon collapsed.
        if ((int)result.size() < 3) return result;
    }
    return result;
}

