// Drop vertices that are collinear with their neighbours, but preserve
// duplicates that arise from S-H intersection points landing exactly on a
// vertex of the input polygon (those duplicates are real extreme-point
// vertices of the convex polygon).
//
// Algorithm: for each vertex v_i, check orientation(v_{i-1}, v_i, v_{i+1}).
// If COLLINEAR, drop v_i.  Iterate until no changes.  For duplicate
// vertices (v_i == v_{i+1}), both are checked: orientation(v_{i-1}, v_i,
// v_{i+1}) == COLLINEAR (since v_i == v_{i+1}), and orientation(v_i,
// v_{i+1}, v_{i+2}) == COLLINEAR (since v_i == v_{i+1}).  Both are dropped
// by the loop.  We compensate by NOT dropping v_i if v_{i-1} == v_i
// (i.e., the previous vertex was already dropped and we'd lose the extreme
// point entirely).
static vector<Point> strip_collinear(const vector<Point>& verts) {
    int n = (int)verts.size();
    if (n < 3) return verts;
    vector<Point> result = verts;
    bool changed = true;
    while (changed) {
        changed = false;
        n = (int)result.size();
        vector<Point> stripped;
        stripped.reserve(n);
        for (int i = 0; i < n; ++i) {
            const Point& a = result[(i - 1 + n) % n];
            const Point& b = result[i];
            const Point& c = result[(i + 1) % n];
            // Drop b only if it's strictly collinear AND its predecessor
            // wasn't itself dropped.  If a == b, then b was the survivor
            // from the previous iteration (a was a duplicate of b), and
            // dropping b here would remove the extreme point entirely.
            if (a == b) {
                stripped.push_back(b);
                continue;
            }
            if (CGAL::orientation(a, b, c) != CGAL::COLLINEAR) {
                stripped.push_back(b);
            } else {
                changed = true;
            }
        }
        result.swap(stripped);
    }
    return result;
}

