static std::mt19937 rng(42);

static vector<Point> random_convex(double r, int n) {
    std::uniform_real_distribution<double> dist(-r, r);
    vector<Point> pts;
    for (int i = 0; i < n * 4; i++) {
        pts.push_back(Point(dist(rng), dist(rng)));
    }
    vector<Point> hull;
    CGAL::convex_hull_2(pts.begin(), pts.end(), std::back_inserter(hull));
    if ((int)hull.size() > n) hull.resize(n);
    return hull;
}

// Strategy 1: dedup then strip_collinear
static vector<Point> clean_v1(const vector<Point>& verts) {
    vector<Point> result = verts;
    bool changed = true;
    while (changed) {
        changed = false;
        // Dedup adjacent identical vertices
        vector<Point> deduped;
        const int n = (int)result.size();
        for (int i = 0; i < n; ++i) {
            if (result[i] != result[(i + 1) % n]) {
                deduped.push_back(result[i]);
            } else {
                changed = true;
            }
        }
        if ((int)deduped.size() < 3) return deduped;
        // Strip collinear
        vector<Point> stripped;
        const int m = (int)deduped.size();
        for (int i = 0; i < m; ++i) {
            const Point& a = deduped[(i - 1 + m) % m];
            const Point& b = deduped[i];
            const Point& c = deduped[(i + 1) % m];
            if (CGAL::orientation(a, b, c) != CGAL::COLLINEAR) {
                stripped.push_back(b);
            } else {
                changed = true;
            }
        }
        result.swap(stripped);
    }
    return result;
}

static void dump(const vector<Point>& P, const char* tag) {
    cout << tag << " (" << P.size() << " verts):";
    for (const auto& p : P) cout << " (" << std::fixed << std::setprecision(2) << CGAL::to_double(p.x()) << "," << CGAL::to_double(p.y()) << ")";
    cout << "\n";
}

int main() {
    int n_trials = 0, n_diff = 0;
    for (int trial = 0; trial < 500; trial++) {
        std::uniform_int_distribution<int> ndist(3, 20);
