static void intersect(const Polygon& subject, const Polygon& clip,
                        std::back_insert_iterator<std::vector<Polygon_with_holes>> result) {
    TIMER("copy_verts");
    std::vector<Point> P_verts(subject.vertices_begin(), subject.vertices_end());
    std::vector<Point> Q_verts(clip.vertices_begin(), clip.vertices_end());

    {
        TIMER("convex_intersect");
        auto verts = convex_intersect_fast(P_verts, Q_verts);
        if (verts.size() < 3) return;
        // Drop redundant collinear-on-edge vertices before constructing the
        // Polygon.  Sutherland-Hodgman can emit collinear vertices when a
        // P-vertex lies on a Q-edge, and these accumulate across iterations
        // of the simplifier cascade — each extra vertex becomes a candidate
        // for the next step, blowing up the simplified output.
        //
        // Two passes: (1) drop exact duplicates of adjacent vertices (the
        // S-H output may emit a Q-vertex followed by an intersection that
        // resolves to the same coordinates); (2) drop vertices whose
        // neighbours are collinear (a vertex on a polygon edge that
        // doesn't bend the polygon).
        //
        // This is equivalent to running convex_hull_2 on the result — both
        // produce the same minimal vertex representation for a convex
        // polygon — but linear-time instead of O(n log n).
        {
            TIMER("strip_collinear");
            std::vector<Point>& cur = verts;
            bool changed = true;
            while (changed && (int)cur.size() >= 3) {
                changed = false;
                // Pass 1: drop adjacent duplicates.
                std::vector<Point> deduped;
                const int n = (int)cur.size();
                for (int i = 0; i < n; ++i) {
                    if (cur[i] != cur[(i + 1) % n]) {
                        deduped.push_back(cur[i]);
                    } else {
                        changed = true;
                    }
                }
                if ((int)deduped.size() < 3) break;
                // Pass 2: drop collinear (after dedup, b == c and a == b are
                // impossible, so a single orientation check suffices).
                std::vector<Point> stripped;
                const int m = (int)deduped.size();
                for (int i = 0; i < m; ++i) {
                    const Point& a = deduped[(i - 1 + m) % m];
                    const Point& b = deduped[i];
                    const Point& c = deduped[(i + 1) % m];
                    if (CGAL::orientation(a, b, c) != CGAL::COLLINEAR) {
                        stripped.push_back(b);
                    } else {
                        changed = true;
                    }
                }
                cur.swap(stripped);
            }
        }
        if (verts.size() < 3) return;
        Polygon inter_poly(verts.begin(), verts.end());
        if (!inter_poly.is_simple()) return;
        if (inter_poly.is_clockwise_oriented()) inter_poly.reverse_orientation();
        *result++ = Polygon_with_holes(inter_poly);
    }

