// matching CGAL::COLLINEAR behaviour.  This is a conservative choice
// for the simplification (it adds at most a collinear vertex, which
// convex_hull_2 then prunes).

// Sign of the cross product (b - a) x (p - a), as doubles.
// Returns +1 if p is to the left of (a, b), -1 if to the right, 0 if collinear.
static inline int cross_sign(const Point& a, const Point& b, const Point& p) {
    const double bx = b.x() - a.x();
    const double by = b.y() - a.y();
    const double px = p.x() - a.x();
    const double py = p.y() - a.y();
    const double c  = bx * py - by * px;
    if (c > 0.0) return +1;
    if (c < 0.0) return -1;
    return 0;
}

