// The hot loop calls this ~10^5 - 10^6 times per case.  Avoids building
// a CGAL::Polygon_2 for the inputs and the output: callers already hold
// the points in std::vector<Point> and only need the resulting vertex
// list back, so going through Polygon/Polygon_with_holes here would be
// pure overhead.
static std::vector<Point> intersect(const std::vector<Point>& subject,
                                    const std::vector<Point>& clip) {
    auto verts = convex_intersect_fast(subject, clip);
    if (verts.size() < 3) return {};
