    // Sutherland-Hodgman can emit collinear vertices when a P-vertex lies
    // on a Q-edge, and these accumulate across iterations of the
    // simplifier cascade — each extra vertex becomes a candidate for the
    // next step, blowing up the simplified output.  convex_hull_2 strips
    // them and gives the minimal vertex representation.
    std::vector<Point> hull;
    CGAL::convex_hull_2(verts.begin(), verts.end(),
                        std::back_inserter(hull));
