// Fast convex polygon intersection: boundary-points + convex-hull.
//
// The key insight is that P ∩ Q is the convex hull of all points that are:
//   1. P-vertices that lie inside Q
//   2. Q-vertices that lie inside P
//   3. P-edge ∩ Q-edge intersection points
//
// Clipping P against Q's half-planes (Sutherland-Hodgman) only produces
// candidates of type 1 and 3, and misses type 2.  This was the bug that
// caused Fréchet to blow up from 283 to 868.
//
// Algorithm:
//   1. Normalize to CCW (Epick area sum is exact for the cross product sum).
//   2. Containment shortcut: if one polygon is entirely inside the other, return it.
//   3. Collect all candidate points of types 1, 2, 3 above (Epick throughout).
//   4. Compute their convex hull.
//
// All geometry uses Epick (exact predicates, inexact constructions).  Orientation
// tests are exact in sign.  Line intersection points are in double, which is fine:
// the hull algorithm is robust to small vertex perturbations.
static std::vector<Point> convex_intersect_fast(const std::vector<Point>& Pin,
                                                 const std::vector<Point>& Qin) {
    if (Pin.size() < 3 || Qin.size() < 3) return {};

    // Normalise both to CCW using kernel_signed_area (Epick cross product sum).
    // The sum of exact cross products is exact, so the sign is correct.
    std::vector<Point> P, Q;
    P.reserve(Pin.size());
    Q.reserve(Qin.size());
    if (kernel_signed_area(Pin) < 0) { P.assign(Pin.rbegin(), Pin.rend()); }
    else                            { P = Pin; }
    if (kernel_signed_area(Qin) < 0) { Q.assign(Qin.rbegin(), Qin.rend()); }
    else                            { Q = Qin; }

