    // Epick (floating-point) kernel_signed_area could misclassify nearly-zero-
    // area polygons, reversing one of them and corrupting the intersection.
    auto signed_area_sign = [](const std::vector<Point>& P) {
        Epeck::FT s = 0;
        int sz = (int)P.size();
