            Epeck::Point_2 a = conv_to_exact(P[i]);
            Epeck::Point_2 b = conv_to_exact(P[(i + 1) % sz]);
            s += a.x() * b.y() - b.x() * a.y();
        }
        return CGAL::sign(s);
    };

