static std::optional<Point> line_intersect(const Point& a, const Point& b,
                                           const Point& p1, const Point& p2) {
    // Guard against degenerate segments.
    if (p1.x() == p2.x() && p1.y() == p2.y()) return p1;
    if (a.x() == b.x() && a.y() == b.y()) {
        return (CGAL::orientation(a, b, p1) != CGAL::RIGHT_TURN)
                   ? std::optional<Point>(p1) : std::nullopt;
    }

    // Use Epick's Line_2 for intersection.  The result is a double-precision
    // Point that lies on both lines.  This is the correct intersection for
    // the half-plane clipping: the clipped polygon vertex must be on the
    // line defined by the edge, not on the finite segment.  Epick's
    // construction is inexact but that's fine — we feed the result back
    // into Epick orientation tests, which remain exact in sign.
    Line line_ab(a, b);
    Line line_p(p1, p2);
    auto inter = CGAL::intersection(line_ab, line_p);
    if (!inter) return std::nullopt;
    if (const Point* ip = std::get_if<Point>(&*inter)) return *ip;
    return std::nullopt;
}

