// candidates of types 1 and 3, MISSING type 2.  This was the bug that caused
// the Fréchet distance to blow up (282 -> 868).
//
// Algorithm: collect all candidate points, sort-deduplicate, take convex hull.
// Complexity: O(|P|*|Q| + k log k).
// All geometry uses Epick (exact predicates, inexact constructions).
static std::vector<Point> convex_intersect_fast(const std::vector<Point>& Pin,
                                                 const std::vector<Point>& Qin) {
    if (Pin.size() < 3 || Qin.size() < 3) return {};

    // Normalise both to CCW using kernel_signed_area.
    std::vector<Point> P, Q;
    P.reserve(Pin.size());
    Q.reserve(Qin.size());
    if (kernel_signed_area(Pin) < 0) { P.assign(Pin.rbegin(), Pin.rend()); }
    else                            { P = Pin; }
    if (kernel_signed_area(Qin) < 0) { Q.assign(Qin.rbegin(), Qin.rend()); }
    else                            { Q = Qin; }

    // Containment shortcuts.
    if (point_in_convex_poly(P[0], Q) && all_points_in_convex_poly(P, Q)) return P;
    if (point_in_convex_poly(Q[0], P) && all_points_in_convex_poly(Q, P)) return Q;

    int n = (int)P.size();
    int m = (int)Q.size();

    // Collect (x, (y, Point)) pairs for deduplication.
    std::vector<std::pair<double, std::pair<double, Point>>> pairs;
    pairs.reserve(n + m + n * m);

    auto add_candidate = [&](const Point& p) {
        double x = CGAL::to_double(p.x());
        double y = CGAL::to_double(p.y());
        pairs.emplace_back(x, std::make_pair(y, p));
    };

    // Type 1: P-vertices inside Q.
    for (int i = 0; i < n; ++i)
        if (point_in_convex_poly(P[i], Q)) add_candidate(P[i]);

    // Type 2: Q-vertices inside P.  THIS IS THE KEY FIX.
    for (int j = 0; j < m; ++j)
        if (point_in_convex_poly(Q[j], P)) add_candidate(Q[j]);

    // Type 3: P-edge ∩ Q-edge intersections.
    for (int i = 0; i < n; ++i) {
        const Point& p1 = P[i];
        const Point& p2 = P[(i + 1) % n];
        for (int j = 0; j < m; ++j) {
            const Point& q1 = Q[j];
            const Point& q2 = Q[(j + 1) % m];
            if (auto ip = line_intersect(p1, p2, q1, q2))
                add_candidate(*ip);
        }
    }

    if (pairs.empty()) return {};

    // Sort by (x, y) and deduplicate.
    std::sort(pairs.begin(), pairs.end(),
              [](const auto& a, const auto& b) {
                  if (a.first != b.first) return a.first < b.first;
                  return a.second.first < b.second.first;
              });

    std::vector<Point> candidates;
    candidates.reserve(pairs.size());
    candidates.push_back(pairs[0].second.second);
    for (size_t i = 1; i < pairs.size(); ++i) {
        if (pairs[i].first != pairs[i-1].first ||
            pairs[i].second.first != pairs[i-1].second.first)
            candidates.push_back(pairs[i].second.second);
    }

    if (candidates.size() < 3) return {};

    std::vector<Point> hull;
    CGAL::convex_hull_2(candidates.begin(), candidates.end(),
                        std::back_inserter(hull));
    return hull;
}
