//
// Returns the intersection polygon in CCW order, or {} if empty.
//
// KEY FIX: The previous S-H clipping version was WRONG. S-H only clips P's
// boundary against Q's half-planes, missing Q-vertices that lie inside P.
// This caused Fréchet to blow up from 282 to 868.  The correct approach
// collects all four candidate sources and takes their convex hull:
//   1. P-vertices inside Q
//   2. Q-vertices inside P     <-- MISSING FROM S-H
//   3. P-edge ∩ Q-edge intersections
static std::vector<Point> convex_intersect_fast(const std::vector<Point>& Pin,
                                                 const std::vector<Point>& Qin) {
    if (Pin.size() < 3 || Qin.size() < 3) return {};

    // Normalise to CCW.
    std::vector<Point> P, Q;
    P.reserve(Pin.size()); Q.reserve(Qin.size());
    if (kernel_signed_area(Pin) < 0) { P.assign(Pin.rbegin(), Pin.rend()); }
    else                            { P = Pin; }
    if (kernel_signed_area(Qin) < 0) { Q.assign(Qin.rbegin(), Qin.rend()); }
    else                            { Q = Qin; }

    // Containment shortcuts.
    if (point_in_convex_poly(P[0], Q) && all_points_in_convex_poly(P, Q)) return P;
    if (point_in_convex_poly(Q[0], P) && all_points_in_convex_poly(Q, P)) return Q;

    int n = (int)P.size(), m = (int)Q.size();

    // Collect candidates.
    std::vector<std::pair<double, std::pair<double, Point>>> pairs;
    pairs.reserve(n + m + n * m);

    auto add = [&](const Point& p) {
        pairs.emplace_back(CGAL::to_double(p.x()), std::make_pair(CGAL::to_double(p.y()), p));
    };

    // Type 1: P-vertices inside Q.
    for (int i = 0; i < n; ++i)
        if (point_in_convex_poly(P[i], Q)) add(P[i]);

    // Type 2: Q-vertices inside P.  <-- THIS IS THE KEY FIX.
    for (int j = 0; j < m; ++j)
        if (point_in_convex_poly(Q[j], P)) add(Q[j]);

    // Type 3: P-edge ∩ Q-edge intersections.
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) {
            if (auto ip = line_intersect(P[i], P[(i+1)%n], Q[j], Q[(j+1)%m]))
                add(*ip);
        }
    }

    if (pairs.empty()) return {};

    // Sort and deduplicate.
    std::sort(pairs.begin(), pairs.end(), [](auto& a, auto& b) {
        if (a.first != b.first) return a.first < b.first;
        return a.second.first < b.second.first;
    });
    std::vector<Point> cand;
    cand.push_back(pairs[0].second.second);
    for (size_t i = 1; i < pairs.size(); ++i)
