            pairs[i].second.first != pairs[i-1].second.first)
            cand.push_back(pairs[i].second.second);

    if (cand.size() < 3) return {};
    std::vector<Point> hull;
    CGAL::convex_hull_2(cand.begin(), cand.end(), std::back_inserter(hull));
    return hull;
