// =============================================================================
//  Geometry primitives and intersection algorithms
//
//  See geometry.h for declarations and the overall design rationale.
// =============================================================================

#include "geometry.h"

#include <CGAL/Cartesian_converter.h>
#include <CGAL/convex_hull_2.h>

namespace {
namespace Epeck = CGAL::Exact_predicates_exact_constructions_kernel;

static Point conv_to_inexact(const Epeck::Point_2& p) {
    return Point(CGAL::to_double(p.x()), CGAL::to_double(p.y()));
}
} // anonymous namespace

// =============================================================================
//  Polygon area
// =============================================================================

double kernel_signed_area(const std::vector<Point>& P) {
    double s = 0.0;
    int sz = (int)P.size();
    for (int i = 0; i < sz; ++i) {
        const Point& a = P[i];
        const Point& b = P[(i + 1) % sz];
        s += CGAL::to_double(a.x() * b.y() - b.x() * a.y());
    }
    return s / 2.0;
}

// =============================================================================
//  Sutherland-Hodgman helpers (Epick)
// =============================================================================

bool point_in_convex_poly(const Point& p, const std::vector<Point>& poly) {
    int n = (int)poly.size();
    for (int i = 0; i < n; ++i) {
        const Point& a = poly[i];
        const Point& b = poly[(i + 1) % n];
        if (CGAL::orientation(a, b, p) == CGAL::RIGHT_TURN) return false;
    }
    return true;
}

bool all_points_in_convex_poly(const std::vector<Point>& inner,
                               const std::vector<Point>& outer) {
    for (const auto& v : inner) {
        if (!point_in_convex_poly(v, outer)) return false;
    }
    return true;
}

// Line-line intersection for the half-plane clipper.  Given a directed edge
// (a, b) defining the "inside" half-plane and a directed input segment
// (p1, p2), return the intersection point of the two lines, or std::nullopt
// if the segments don't intersect (parallel/collinear case).
//
// Use Epeck for exact intersection construction.  The clip edge and subject
// segment endpoints are converted to Epeck, their intersection is computed
// exactly, and the result is converted back to Epick (our Point type).
// This avoids the floating-point rounding that occurs with Epick Line_2
// intersection, which causes slightly-off intersection vertices that corrupt
// subsequent clipping steps and ultimately the Fréchet bound.
std::optional<Point> line_intersect(const Point& a, const Point& b,
                                    const Point& p1, const Point& p2) {
    if (p1.x() == p2.x() && p1.y() == p2.y()) return p1;
    if (a.x() == b.x() && a.y() == b.y()) {
        return (CGAL::orientation(a, b, p1) != CGAL::RIGHT_TURN)
                   ? std::optional<Point>(p1) : std::nullopt;
    }

    Epeck::Point_2 ae(CGAL::exact(a.x()), CGAL::exact(a.y()));
    Epeck::Point_2 be(CGAL::exact(b.x()), CGAL::exact(b.y()));
    Epeck::Point_2 p1e(CGAL::exact(p1.x()), CGAL::exact(p1.y()));
    Epeck::Point_2 p2e(CGAL::exact(p2.x()), CGAL::exact(p2.y()));

    Epeck::Segment_2 seg_ab(ae, be);
    Epeck::Segment_2 seg_p(p1e, p2e);
    auto inter = CGAL::intersection(seg_ab, seg_p);
    if (!inter) return std::nullopt;        // parallel or coincident lines
    if (const Epeck::Point_2* ip = std::get_if<Epeck::Point_2>(&*inter)) {
        return conv_to_inexact(*ip);
    }
    return std::nullopt;                    // coincident lines
}

// Sutherland-Hodgman half-plane clip.  `subject` is a CCW convex polygon;
// the half-plane is defined by directed edge (a, b) with the inside being
// the LEFT side (i.e. orientation(a, b, p) != RIGHT_TURN).
//
// Used by convex_intersect_fast: for each edge of the `clip` polygon we
// clip the running subject against that half-plane.  After |clip| edges
// the running subject is exactly `subject ∩ clip`.
std::vector<Point> clip_halfplane(const std::vector<Point>& subject,
                                  const Point& a, const Point& b) {
    int n = (int)subject.size();
    if (n == 0) return {};

    std::vector<Point> out;
    out.reserve(n + 1);

    auto o_prev = CGAL::orientation(a, b, subject[(n - 1) % n]);
    bool prev_in = (o_prev != CGAL::RIGHT_TURN);

    for (int i = 0; i < n; ++i) {
        const Point& cur  = subject[i];
        auto o_cur  = CGAL::orientation(a, b, cur);
        bool cur_in  = (o_cur != CGAL::RIGHT_TURN);

        if (cur_in) {
            if (!prev_in) {
                if (auto ip = line_intersect(a, b, subject[(i + n - 1) % n], cur))
                    out.push_back(*ip);
            }
            out.push_back(cur);
        } else if (prev_in) {
            if (auto ip = line_intersect(a, b, subject[(i + n - 1) % n], cur))
                out.push_back(*ip);
        }
        prev_in = cur_in;
    }
    return out;
}

// =============================================================================
//  Sutherland-Hodgman convex-convex intersection (top-level)
// =============================================================================

std::vector<Point> convex_intersect_fast(const std::vector<Point>& Pin,
                                         const std::vector<Point>& Qin) {
    if (Pin.size() < 3 || Qin.size() < 3) return {};

    // Normalise both to CCW.  Epick's orientation is exact in sign, and
    // the sum of cross products a.x()*b.y() - b.x()*a.y() over a CCW
    // polygon is exactly positive (the predicates stay exact).  We fall
    // back to the all-points-inside shortcut for the rare case where
    // the area rounds to zero (a polygon with three collinear edges).
    std::vector<Point> P, Q;
    P.reserve(Pin.size());
    Q.reserve(Qin.size());
    if (kernel_signed_area(Pin) < 0) { P.assign(Pin.rbegin(), Pin.rend()); }
    else                            { P = Pin; }
    if (kernel_signed_area(Qin) < 0) { Q.assign(Qin.rbegin(), Qin.rend()); }
    else                            { Q = Qin; }

    // Containment shortcuts: if one polygon is entirely inside the other,
    // return the inner one.  We test P[0] inside Q (and vice versa), then
    // validate that ALL vertices of the inner polygon are inside the outer
    // one — a single false positive (e.g. a shared boundary vertex
    // misclassified) would silently return the wrong polygon and corrupt
    // the Fréchet bound.
    if (point_in_convex_poly(P[0], Q) && all_points_in_convex_poly(P, Q)) return P;
    if (point_in_convex_poly(Q[0], P) && all_points_in_convex_poly(Q, P)) return Q;

    // Otherwise clip P against each edge of Q.
    std::vector<Point> running = P;
    int m = (int)Q.size();
    for (int i = 0; i < m; ++i) {
        const Point& a = Q[i];
        const Point& b = Q[(i + 1) % m];
        running = clip_halfplane(running, a, b);
        if (running.size() < 3) return {};   // intersection empty
    }
    return running;
}

