    if (a.x() == b.x() && a.y() == b.y()) {
        return (CGAL::orientation(a, b, p1) != CGAL::RIGHT_TURN)
                   ? std::optional<Point>(p1) : std::nullopt;
    }

    // Exact intersection of infinite lines (a,b) and (p1,p2).
    // Line AB: ax + by = c where c = ax0*by1 - ax1*by0 (cross product)
    // Line P:  px + qy = r where r = px0*qy1 - px1*qy0
