    // the Epick rounding that caused vertex explosion), then convert back.
    {
        TIMER("convex_hull");
        std::vector<CGAL::Epeck::Point_2> epeck_verts;
        epeck_verts.reserve(verts.size());
        for (const auto& p : verts) {
            epeck_verts.emplace_back(p.x(), p.y());
        }
        std::vector<CGAL::Epeck::Point_2> epeck_hull;
        CGAL::convex_hull_2(epeck_verts.begin(), epeck_verts.end(),
                             std::back_inserter(epeck_hull));
        verts.clear();
        verts.reserve(epeck_hull.size());
        for (const auto& p : epeck_hull) {
            verts.emplace_back(CGAL::to_double(p.x()),
                               CGAL::to_double(p.y()));
        }
    }
    return verts;
}

