static std::vector<Point> intersect(const std::vector<Point>& subject,
                                    const std::vector<Point>& clip) {
    auto verts = convex_intersect_fast(subject, clip);
    if (verts.size() < 3) return {};
    // Epeck intersection is exact.  Compute convex hull in Epeck (to avoid
    // re-rounding exact points through Epick), then convert back.
    std::vector<CGAL::Epeck::Point_2> epeck_verts;
    epeck_verts.reserve(verts.size());
    for (const auto& p : verts)
        epeck_verts.emplace_back(p.x(), p.y());
    std::vector<CGAL::Epeck::Point_2> epeck_hull;
    CGAL::convex_hull_2(epeck_verts.begin(), epeck_verts.end(),
                         std::back_inserter(epeck_hull));
    verts.clear();
    verts.reserve(epeck_hull.size());
    for (const auto& p : epeck_hull)
        verts.emplace_back(CGAL::to_double(p.x()), CGAL::to_double(p.y()));
    return verts;
}

