// Point-in-convex-polygon test, used only for the "boundaries don't cross"
// closure (one polygon entirely inside the other, or single touching point).
// Use Epeck orientation for bit-exact results — Epick's orientation can
// return LEFT_TURN for points that are exactly on a shared edge in exact
// arithmetic, which would cause the containment shortcut to incorrectly
// return the outer polygon (corrupting the Fréchet bound).
static bool point_in_convex_poly(const Point& p, const std::vector<Point>& poly) {
    int n = (int)poly.size();
    Epeck::Point_2 pe = conv_to_exact(p);
    for (int i = 0; i < n; ++i) {
        Epeck::Point_2 a = conv_to_exact(poly[i]);
        Epeck::Point_2 b = conv_to_exact(poly[(i + 1) % n]);
        if (CGAL::orientation(a, b, pe) == CGAL::RIGHT_TURN) return false;
    }
    return true;
}

