// Same as area_sign but for vector triples.  Used inside the main loop
// where A and B are the *edge vectors* of the two polygons, not points.
// Use Epeck for exact determinant — Epick returns 0 for nearly-parallel
// edges due to rounding, causing O'Rourke to take the "parallel" path
// and miss legitimate intersection points.
static int area_sign_vec(const Vector& a, const Vector& b) {
    Epeck::Vector_2 ae = conv_to_exact(a);
    Epeck::Vector_2 be = conv_to_exact(b);
    auto c = CGAL::determinant(ae, be);
    if (c > 0) return  1;
    if (c < 0) return -1;
    return 0;
}

