// results — Epick's orientation can return COLLINEAR for points that are
// exactly not collinear in exact arithmetic (when the cross product rounds
// to 0), causing O'Rourke to take the wrong path.
static int area_sign(const Point& a, const Point& b, const Point& c) {
    switch (CGAL::orientation(conv_to_exact(a), conv_to_exact(b), conv_to_exact(c))) {
        case CGAL::LEFT_TURN:  return  1;
        case CGAL::RIGHT_TURN: return -1;
        case CGAL::COLLINEAR:  return  0;
