// Compute the intersection of two convex polygons given as point
// vectors.  Returns the intersection polygon (also a vector of points)
// or an empty vector if the intersection is empty (or has fewer than
// 3 vertices).
//
// Algorithm: candidate-point + convex hull.  The intersection of two
// convex polygons consists of:
//   (a) vertices of `subject` that lie inside `clip`
//   (b) vertices of `clip` that lie inside `subject`
//   (c) intersection points of subject edges with clip edges
// We collect all candidate points (a) + (b) + (c), then compute the
// convex hull.  This is much simpler than Sutherland-Hodgman clipping
// and avoids the rounding errors that compound across many iterations.
//
// The hot loop calls this ~10^5 - 10^6 times per case, so we deliberately
// avoid building CGAL::Polygon_2 / Polygon_with_holes_2 wrappers here:
// callers already hold the points in std::vector<Point> and only need
// the resulting vertex list back.
static std::vector<Point> intersect(const std::vector<Point>& subject,
                                    const std::vector<Point>& clip) {
    std::vector<Point> candidates;

    // (a) Subject vertices inside clip.  Epick orientation is exact in
    // sign, so a vertex on a shared boundary edge is classified exactly.
    // Such collinear vertices are kept — they will be removed by convex_hull_2.
    for (const auto& v : subject) {
        if (point_in_convex(v, clip)) {
            candidates.push_back(v);
        }
    }
    // (b) Clip vertices inside subject.
    for (const auto& v : clip) {
        if (point_in_convex(v, subject)) {
            candidates.push_back(v);
        }
    }
    // (c) Edge-edge intersection points.  Use Epeck for exact construction.
    int n = (int)subject.size();
    int m = (int)clip.size();
    for (int i = 0; i < n; ++i) {
        const Point& a = subject[i];
        const Point& b = subject[(i + 1) % n];
        for (int j = 0; j < m; ++j) {
            const Point& c = clip[j];
            const Point& d = clip[(j + 1) % m];
            // Use Epeck for exact intersection construction.
            CGAL::Epeck::Point_2 ae(a.x(), a.y()), be(b.x(), b.y());
            CGAL::Epeck::Point_2 ce(c.x(), c.y()), de(d.x(), d.y());
            CGAL::Epeck::Segment_2 seg_ab(ae, be), seg_cd(ce, de);
            auto inter = CGAL::intersection(seg_ab, seg_cd);
            if (!inter) continue;
            if (const CGAL::Epeck::Point_2* ip =
                    std::get_if<CGAL::Epeck::Point_2>(&*inter)) {
                candidates.emplace_back(CGAL::to_double(ip->x()),
                                         CGAL::to_double(ip->y()));
            }
        }
    }

    if (candidates.size() < 3) return {};

    // Drop collinear-on-edge vertices and keep only the hull vertices.
    // CGAL::convex_hull_2 uses Epick internally, so the result vertices
    // may differ by sub-ulp from the Epeck candidates.  This is fine:
    // orientation tests against the hull vertices are still exact in sign.
    std::vector<Point> hull;
    CGAL::convex_hull_2(candidates.begin(), candidates.end(),
                        std::back_inserter(hull));
    return hull;
}

