// Compute the intersection of two convex polygons given as point
// vectors.  Returns the intersection polygon (also a vector of points)
// or an empty vector if the intersection is empty (or has fewer than
// 3 vertices).
//
// Uses CGAL::intersection (Epeck internally) for correctness — it is
// the gold standard for polygon intersection.  We wrap the input as
// Polygon_2, run CGAL::intersection, and convert the result back to
// std::vector<Point>.  This is the production-correctness baseline.
static std::vector<Point> intersect(const std::vector<Point>& subject,
                                    const std::vector<Point>& clip) {
    if (subject.size() < 3 || clip.size() < 3) return {};
    // CGAL::Polygon asserts on duplicate consecutive vertices.  Strip them.
    auto dedup_consecutive = [](std::vector<Point> v) {
        std::vector<Point> out;
        out.reserve(v.size());
        for (auto& p : v) {
            if (!out.empty() && out.back().x() == p.x() && out.back().y() == p.y())
                continue;
            out.push_back(p);
        }
        return out;
    };
    auto subj = dedup_consecutive(subject);
    auto clp = dedup_consecutive(clip);
    if (subj.size() < 3 || clp.size() < 3) return {};
    std::vector<Point> ret;
    try {
        Polygon sub_poly(subj.begin(), subj.end());
        Polygon clp_poly(clp.begin(), clp.end());
        std::vector<Polygon_with_holes> result;
        CGAL::intersection(sub_poly, clp_poly, std::back_inserter(result));
        if (result.empty()) return {};
        const auto& outer = result[0].outer_boundary();
        if (outer.size() < 3) return {};
        ret.assign(outer.begin(), outer.end());
    } catch (...) {
        return {};
    }
    // Ensure counter-clockwise (CGAL's intersection may return either order,
    // and find_F assumes CCW).
    try {
        Polygon p(ret.begin(), ret.end());
        if (!p.is_counterclockwise_oriented()) {
            std::reverse(ret.begin(), ret.end());
        }
    } catch (...) {
        // Polygon ctor threw on degenerate output; just return as-is.
    }
    return ret;
}

