// Compute the intersection of two convex polygons given as point
// vectors.  Returns the intersection polygon (also a vector of points)
// or an empty vector if the intersection is empty (or has fewer than
// 3 vertices).
//
// Algorithm: candidate-point + convex hull.  The intersection of two
// convex polygons consists of:
//   (a) vertices of `subject` that lie inside `clip`
//   (b) vertices of `clip` that lie inside `subject`
//   (c) intersection points of subject edges with clip edges
// We collect all candidate points (a) + (b) + (c), then compute the
// convex hull.  However, convex_hull_2 drops collinear points, which
// can lose vertices that CGAL::intersection preserves (e.g., a clip
// vertex that sits on a subject edge).  So after the hull, we re-add
// any subject or clip vertex that lies on the boundary of the hull.
static std::vector<Point> intersect(const std::vector<Point>& subject,
                                    const std::vector<Point>& clip) {
    std::vector<Point> candidates;

    for (const auto& v : subject) {
        if (point_in_convex(v, clip)) candidates.push_back(v);
    }
    for (const auto& v : clip) {
        if (point_in_convex(v, subject)) candidates.push_back(v);
    }
    int n = (int)subject.size(), m = (int)clip.size();
    for (int i = 0; i < n; ++i) {
        const Point& a = subject[i];
        const Point& b = subject[(i + 1) % n];
        for (int j = 0; j < m; ++j) {
            const Point& c = clip[j];
            const Point& d = clip[(j + 1) % m];
            CGAL::Epeck::Point_2 ae(a.x(), a.y()), be(b.x(), b.y());
            CGAL::Epeck::Point_2 ce(c.x(), c.y()), de(d.x(), d.y());
            CGAL::Epeck::Segment_2 seg_ab(ae, be), seg_cd(ce, de);
            auto inter = CGAL::intersection(seg_ab, seg_cd);
            if (!inter) continue;
            if (const CGAL::Epeck::Point_2* ip =
                    std::get_if<CGAL::Epeck::Point_2>(&*inter)) {
                candidates.emplace_back(CGAL::to_double(ip->x()),
                                         CGAL::to_double(ip->y()));
            }
        }
    }

    if (candidates.size() < 3) return {};

    // Deduplicate candidates (Epeck exact comparison).
    std::vector<CGAL::Epeck::Point_2> epeck_candidates;
    epeck_candidates.reserve(candidates.size());
    for (const auto& p : candidates) {
        CGAL::Epeck::Point_2 pe(p.x(), p.y());
        bool dup = false;
        for (const auto& q : epeck_candidates) {
            if (pe == q) { dup = true; break; }
        }
        if (!dup) epeck_candidates.push_back(pe);
    }

    // Convex hull in Epeck.
    std::vector<CGAL::Epeck::Point_2> epeck_hull;
    CGAL::convex_hull_2(epeck_candidates.begin(), epeck_candidates.end(),
                         std::back_inserter(epeck_hull));

    // Re-insert any subject or clip vertex that lies on the boundary of the
    // hull.  This preserves collinear vertices that CGAL::intersection keeps
    // but convex_hull_2 drops.  Only insert points that are between two hull
    // vertices (not the same as a hull vertex).
    std::set<std::pair<CGAL::Epeck::Point_2, int>> hull_set;
    for (size_t i = 0; i < epeck_hull.size(); ++i) {
        hull_set.insert({epeck_hull[i], (int)i});
    }
    auto is_hull_vertex = [&](const CGAL::Epeck::Point_2& p) {
        for (const auto& q : epeck_hull)
            if (p == q) return true;
        return false;
    };
    auto insert_into_hull = [&](CGAL::Epeck::Point_2 p) {
        // Find the edge (i, i+1) of the hull that contains p on it.
        for (size_t i = 0; i < epeck_hull.size(); ++i) {
            const CGAL::Epeck::Point_2& a = epeck_hull[i];
            const CGAL::Epeck::Point_2& b = epeck_hull[(i + 1) % epeck_hull.size()];
            if (CGAL::orientation(a, b, p) != CGAL::COLLINEAR) continue;
            // Check p is between a and b.
            if (CGAL::squared_distance(a, b) <
                CGAL::squared_distance(a, p) + CGAL::squared_distance(p, b) - 1e-9) {
                epeck_hull.insert(epeck_hull.begin() + i + 1, p);
                return;
            }
        }
    };
    for (const auto& v : subject) {
        CGAL::Epeck::Point_2 pe(v.x(), v.y());
        if (is_hull_vertex(pe)) continue;
        insert_into_hull(pe);
    }
    for (const auto& v : clip) {
        CGAL::Epeck::Point_2 pe(v.x(), v.y());
        if (is_hull_vertex(pe)) continue;
        insert_into_hull(pe);
    }

    std::vector<Point> hull;
    hull.reserve(epeck_hull.size());
    for (const auto& p : epeck_hull) {
        hull.emplace_back(CGAL::to_double(p.x()), CGAL::to_double(p.y()));
    }
    return hull;
}

