// 3 vertices).
//
// The hot loop calls this ~10^5 - 10^6 times per case, so we deliberately
// avoid building CGAL::Polygon_2 / Polygon_with_holes_2 wrappers here:
// callers already hold the points in std::vector<Point> and only need
// the resulting vertex list back, so going through Polygon machinery
// would be pure overhead.  See profile: copy_verts (Polygon ->
// std::vector) was 4.9 us/call * 850k = 4.2 s on case 10.
static std::vector<Point> intersect(const std::vector<Point>& subject,
                                    const std::vector<Point>& clip) {
    auto verts = convex_intersect_fast(subject, clip);
    if (verts.size() < 3) return {};
    // Drop redundant collinear-on-edge vertices before returning.
    // Sutherland-Hodgman can emit collinear vertices when a P-vertex
    // lies on a Q-edge, and these accumulate across iterations of the
    // simplifier cascade - each extra vertex becomes a candidate for
    // the next step, blowing up the simplified output.  convex_hull_2
    // strips them and gives the minimal vertex representation.
    std::vector<Point> hull;
    CGAL::convex_hull_2(verts.begin(), verts.end(),
                        std::back_inserter(hull));
    return hull;
}

