// Compute the intersection of two convex polygons given as point
// vectors.  Returns the intersection polygon (also a vector of points)
// or an empty vector if the intersection is empty (or has fewer than
// 3 vertices).
//
// Uses CGAL::intersection (Epeck internally) as the gold standard.  On
// failure (degenerate input, etc.) falls back to candidate-point +
// convex hull with collinear re-insertion.
static std::vector<Point> intersect(const std::vector<Point>& subject,
                                    const std::vector<Point>& clip) {
    if (subject.size() < 3 || clip.size() < 3) return {};

    // Sanitize: drop duplicate consecutive vertices and degenerate zero-
    // length edges.  CGAL::Polygon asserts on duplicates and may misbehave
    // on collinear edges.
    auto sanitize = [](const std::vector<Point>& v) -> std::vector<Point> {
        std::vector<Point> out;
        out.reserve(v.size());
        for (const auto& p : v) {
            if (!out.empty() && out.back().x() == p.x() && out.back().y() == p.y())
                continue;
            out.push_back(p);
        }
        // Drop vertices whose incident edges are both zero-length.
        auto is_zero = [](const Point& a, const Point& b) {
            return a.x() == b.x() && a.y() == b.y();
        };
        int n = (int)out.size();
        std::vector<Point> out2;
        out2.reserve(n);
        for (int i = 0; i < n; ++i) {
            const Point& prev = out[(i - 1 + n) % n];
            const Point& cur  = out[i];
            const Point& next = out[(i + 1) % n];
            if (is_zero(prev, cur) && is_zero(cur, next)) continue;
            out2.push_back(cur);
        }
        return out2;
    };
    auto subj = sanitize(subject);
    auto clp = sanitize(clip);
    if (subj.size() < 3 || clp.size() < 3) return {};

    // CGAL::intersection (Epeck based) is the gold standard.
    std::vector<Point> cgal_ret;
    try {
        Polygon sub_poly(subj.begin(), subj.end());
        Polygon clp_poly(clp.begin(), clp.end());
        std::vector<Polygon_with_holes> result;
        CGAL::intersection(sub_poly, clp_poly, std::back_inserter(result));
        if (!result.empty()) {
            const auto& outer = result[0].outer_boundary();
            if (outer.size() >= 3) {
                cgal_ret.assign(outer.begin(), outer.end());
                if (cgal_ret.size() >= 2 && cgal_ret.front().x() == cgal_ret.back().x() &&
                    cgal_ret.front().y() == cgal_ret.back().y()) {
                    cgal_ret.pop_back();
                }
            }
        }
    } catch (...) {}
    if (cgal_ret.size() >= 3) return cgal_ret;

    // Fallback: candidate-point + convex hull + collinear re-insertion.
    std::vector<Point> candidates;
    for (const auto& v : subj) {
        if (point_in_convex(v, clp)) candidates.push_back(v);
    }
    for (const auto& v : clp) {
        if (point_in_convex(v, subj)) candidates.push_back(v);
    }
    int n = (int)subj.size(), m = (int)clp.size();
    for (int i = 0; i < n; ++i) {
        const Point& a = subj[i];
        const Point& b = subj[(i + 1) % n];
        for (int j = 0; j < m; ++j) {
            const Point& c = clp[j];
            const Point& d = clp[(j + 1) % m];
            CGAL::Epeck::Point_2 ae(a.x(), a.y()), be(b.x(), b.y());
            CGAL::Epeck::Point_2 ce(c.x(), c.y()), de(d.x(), d.y());
            CGAL::Epeck::Segment_2 seg_ab(ae, be), seg_cd(ce, de);
            auto inter = CGAL::intersection(seg_ab, seg_cd);
            if (!inter) continue;
            if (const CGAL::Epeck::Point_2* ip =
                    std::get_if<CGAL::Epeck::Point_2>(&*inter)) {
                candidates.emplace_back(CGAL::to_double(ip->x()),
                                         CGAL::to_double(ip->y()));
            }
        }
    }
    if (candidates.size() < 3) return {};

    std::vector<CGAL::Epeck::Point_2> epeck_candidates;
    epeck_candidates.reserve(candidates.size());
    for (const auto& p : candidates) {
        CGAL::Epeck::Point_2 pe(p.x(), p.y());
        bool dup = false;
        for (const auto& q : epeck_candidates) {
            if (pe == q) { dup = true; break; }
        }
        if (!dup) epeck_candidates.push_back(pe);
    }
    std::vector<CGAL::Epeck::Point_2> epeck_hull;
    CGAL::convex_hull_2(epeck_candidates.begin(), epeck_candidates.end(),
                         std::back_inserter(epeck_hull));
    auto is_hull_vertex = [&](const CGAL::Epeck::Point_2& p) {
        for (const auto& q : epeck_hull) if (p == q) return true;
        return false;
    };
    auto insert_into_hull = [&](CGAL::Epeck::Point_2 p) {
        for (size_t i = 0; i < epeck_hull.size(); ++i) {
            const CGAL::Epeck::Point_2& a = epeck_hull[i];
            const CGAL::Epeck::Point_2& b = epeck_hull[(i + 1) % epeck_hull.size()];
            if (CGAL::orientation(a, b, p) != CGAL::COLLINEAR) continue;
            double dab = CGAL::to_double(CGAL::squared_distance(a, b));
            double dap = CGAL::to_double(CGAL::squared_distance(a, p));
            double dpb = CGAL::to_double(CGAL::squared_distance(p, b));
            if (dap > 0 && dpb > 0 && dap + dpb <= dab + 1e-6) {
                epeck_hull.insert(epeck_hull.begin() + i + 1, p);
                return;
            }
        }
    };
    for (const auto& v : subj) {
        CGAL::Epeck::Point_2 pe(v.x(), v.y());
        if (is_hull_vertex(pe)) continue;
        insert_into_hull(pe);
    }
    for (const auto& v : clp) {
        CGAL::Epeck::Point_2 pe(v.x(), v.y());
        if (is_hull_vertex(pe)) continue;
        insert_into_hull(pe);
    }

    std::vector<Point> hull;
    hull.reserve(epeck_hull.size());
    for (const auto& p : epeck_hull) {
        hull.emplace_back(CGAL::to_double(p.x()), CGAL::to_double(p.y()));
    }
    return hull;
}

