    // result.  Polygons can be degenerate; CGAL::intersection asserts in
    // that case, so guard with try/catch.  When the result disagrees with
    // ours, we still return ours (fast path) but log the diff for offline
    // analysis to /tmp/intersect_diff.txt.
    static int diff_log_calls = 0;
    auto log_diff = [&](const std::vector<Point>& mine) {
        if (diff_log_calls >= 20) return;
        try {
            Polygon sub_poly(subject.begin(), subject.end());
            Polygon clp_poly(clip.begin(), clip.end());
            std::vector<Polygon_with_holes> gt_pwh;
            CGAL::intersection(sub_poly, clp_poly, std::back_inserter(gt_pwh));
            size_t gt_n = gt_pwh.empty() ? 0 : gt_pwh[0].outer_boundary().size();
            size_t mine_n = mine.size();
            if (gt_n != mine_n) {
                std::ofstream f("/tmp/intersect_diff.txt", std::ios::app);
                f << "DIFF: mine=" << mine_n << " GT=" << gt_n
                  << " subj=" << subject.size() << " clip=" << clip.size() << "\n";
                if (!gt_pwh.empty()) {
                    for (auto it = gt_pwh[0].outer_boundary().begin();
                         it != gt_pwh[0].outer_boundary().end(); ++it)
                        f << "(" << CGAL::to_double(it->x()) << "," << CGAL::to_double(it->y()) << ") ";
                    f << "\n";
