// Compute the intersection of two convex polygons given as point
// vectors.  Returns the intersection polygon (also a vector of points)
// or an empty vector if the intersection is empty (or has fewer than
// 3 vertices).
//
// Algorithm: CGAL::intersection (treated as ground truth).  We sanitize
// the input polygons first to avoid CGAL assertions on degenerate
// inputs (duplicate vertices, collinear sequences), call CGAL::intersection,
// then convert the resulting Polygon_with_holes back to a point vector.
static std::vector<Point> intersect(const std::vector<Point>& subject,
                                    const std::vector<Point>& clip) {
    if (subject.size() < 3 || clip.size() < 3) return {};

    // Sanitize: drop consecutive duplicates and points within TOL of
    // the previous one to avoid CGAL asserting on degenerate polygons.
    auto sanitize = [](const std::vector<Point>& in) {
        std::vector<Point> out;
        out.reserve(in.size());
        for (const auto& p : in) {
            if (out.empty()) { out.push_back(p); continue; }
            const Point& q = out.back();
            double dx = p.x() - q.x(), dy = p.y() - q.y();
            if (dx*dx + dy*dy < TOL * TOL) continue;
            out.push_back(p);
        }
        // Close the loop check: drop last if same as first.
        if (out.size() >= 2) {
            const Point& f = out.front();
            const Point& b = out.back();
            double dx = f.x() - b.x(), dy = f.y() - b.y();
            if (dx*dx + dy*dy < TOL * TOL) out.pop_back();
        }
        return out;
    };
    auto safe_sub = sanitize(subject);
    auto safe_clp = sanitize(clip);
    if (safe_sub.size() < 3 || safe_clp.size() < 3) return {};

    try {
        Polygon sub_poly(safe_sub.begin(), safe_sub.end());
        Polygon clp_poly(safe_clp.begin(), safe_clp.end());
        std::vector<Polygon_with_holes> pwh;
        CGAL::intersection(sub_poly, clp_poly, std::back_inserter(pwh));
        if (pwh.empty()) return {};
        const auto& outer = pwh[0].outer_boundary();
        std::vector<Point> out;
        out.reserve(outer.size());
        for (auto it = outer.begin(); it != outer.end(); ++it)
            out.emplace_back(CGAL::to_double(it->x()), CGAL::to_double(it->y()));
        return out;
    } catch (...) {
        // CGAL::intersection failed (shouldn't happen with sanitized input);
        // fall back to empty so the algorithm can continue.
        return {};
    }
}

