// Re-insert any subject or clip vertex that lies on the boundary of
    // the hull (between two hull vertices).  This preserves collinear
    // vertices that CGAL::intersection keeps but convex_hull_2 drops.
    auto is_hull_vertex = [&](const Point& p) {
        for (const auto& q : hull_pts) {
            double dx = p.x() - q.x(), dy = p.y() - q.y();
            if (dx*dx + dy*dy < TOL * TOL) return true;
        }
        return false;
    };
    auto insert_into_hull = [&](Point p) {
        if (is_hull_vertex(p)) return;  // avoid duplicate insertion
        for (size_t i = 0; i < hull_pts.size(); ++i) {
            const Point& a = hull_pts[i];
            const Point& b = hull_pts[(i + 1) % hull_pts.size()];
            // Accept exact collinearity OR near-collinearity (within
            // floating-point tolerance) — the construction values for
            // these vertices come from arithmetic on doubles, so even
            // "exactly" collinear points can be slightly off.
            auto det = CGAL::determinant(
                Vector(b.x() - a.x(), b.y() - a.y()),
                Vector(p.x() - a.x(), p.y() - a.y()));
            double dab_lin = std::sqrt(CGAL::to_double(CGAL::squared_distance(a, b)));
            double det_abs = std::abs(CGAL::to_double(det));
            if (det_abs > 1e-6 * dab_lin) continue;  // not close enough
            double dab = CGAL::to_double(CGAL::squared_distance(a, b));
            double dap = CGAL::to_double(CGAL::squared_distance(a, p));
            double dpb = CGAL::to_double(CGAL::squared_distance(p, b));
            if (dap > 0 && dpb > 0 && dap + dpb <= dab * 1.0001) {
                hull_pts.insert(hull_pts.begin() + i + 1, p);
                return;
            }
        }
    };

