// Iterate over grid rows whose y-distance from p is at most R_val(),
// calling fn(px, py, y_actual, x_min, x_max) once per row.  `y_actual`
// is the row's y-coordinate, and x_min/x_max are the integer GRID-step
// extents (relative to the row origin) of the row's intersection with
// the disk of radius R_val() centered on p.
//
// This is used by both get_conv_from_grid (which emits the LEFT and
// RIGHT edge point of each row) and get_points_from_grid (which emits
// every corner in the row).
template <typename F>
static void for_each_grid_row(double px, double py, F&& fn) {
    const double GRID = GRID_val();
    const double R = R_val();
    const double r2 = R * R;
    const int y_min_int = static_cast<int>(-R / GRID) - 1;
    const int y_max_int = static_cast<int>(+R / GRID) + 1;
    for (int y = y_min_int; y <= y_max_int; ++y) {
        const double y_actual = y * GRID;
        const double dy2 = y_actual * y_actual;
        if (dy2 > r2) continue;
        const double dx = std::sqrt(r2 - dy2);
        const int x_min = static_cast<int>(-dx / GRID - 1);
        const int x_max = static_cast<int>(+dx / GRID + 1);
        fn(px, py, y_actual, x_min, x_max);
    }
}

std::vector<Point> get_conv_from_grid(const Point &p) {
    const double px = CGAL::to_double(p.x());
    const double py = CGAL::to_double(p.y());
    std::vector<Point> boundaries;
    for_each_grid_row(px, py, [&](double px_, double py_,
                                  double y_actual, int x_min, int x_max) {
        boundaries.emplace_back(px_ + x_min * GRID_val(), py_ + y_actual);
