static void intersect(const Polygon& subject, const Polygon& clip,
                        std::back_insert_iterator<std::vector<Polygon_with_holes>> result) {
    std::vector<Point> P_verts, Q_verts;
    {
        TIMER("copy_verts");
        P_verts.reserve(subject.size());
        Q_verts.reserve(clip.size());
        for (auto it = subject.vertices_begin(); it != subject.vertices_end(); ++it) {
            P_verts.push_back(*it);
        }
        for (auto it = clip.vertices_begin(); it != clip.vertices_end(); ++it) {
            Q_verts.push_back(*it);
        }
    }

    std::vector<Point> verts;
    {
        TIMER("convex_intersect");
        verts = orourke_cgal::convex_intersect(P_verts, Q_verts);
    }
    // Drop the duplicated closing vertex (O'Rourke appends p0 at the end to
    // close the ring; CGAL::Polygon stores an open ring, so leaving the
    // duplicate in produces a polygon with a spurious zero-length edge that
    // later breaks find_F's tangent search).
    if (verts.size() < 4) return;            // < 3 real vertices -> nothing
    if (verts.front() == verts.back())
        verts.pop_back();

    // The intersection should be convex, hence simple.  But the O'Rourke
    // main loop can emit kinks / collinear vertices that confuse CGAL's
    // is_simple_2 check; ensure the output is well-formed before constructing
    // a Polygon (whose constructor asserts is_simple_2).
    Polygon inter_poly(verts.begin(), verts.end());
    if (!inter_poly.is_simple()) return;
    if (inter_poly.is_clockwise_oriented()) inter_poly.reverse_orientation();

    // Ground-truth cross-check using CGAL::intersection with Epeck kernel.
    // If O'Rourke's result disagrees with the ground truth, use the GT
    // result instead.  This is essential for correctness on cases like
    // case 9 where O'Rourke's polygon omits a vertex that the algorithm
    // later assumes is present, blowing the Fréchet bound.
    static int diff_log_calls = 0;
    static int gt_replaced = 0;
    try {
        using EpeckPoly = CGAL::Polygon_2<CGAL::Epeck>;
        using EpeckPWH  = CGAL::Polygon_with_holes_2<CGAL::Epeck>;
        EpeckPoly sub_poly, clp_poly;
        for (const auto& p : subject)
            sub_poly.push_back(CGAL::Epeck::Point_2(p.x(), p.y()));
        for (const auto& p : clip)
            clp_poly.push_back(CGAL::Epeck::Point_2(p.x(), p.y()));
        std::vector<EpeckPWH> gt_pwh;
        CGAL::intersection(sub_poly, clp_poly, std::back_inserter(gt_pwh));
        if (!gt_pwh.empty()) {
            const auto& gt_outer = gt_pwh[0].outer_boundary();
            size_t gt_n = 0;
            for (auto it = gt_outer.begin(); it != gt_outer.end(); ++it) {
                const auto* nx = (it + 1 == gt_outer.end())
                                 ? &*gt_outer.begin() : &*(it + 1);
                double dx = CGAL::to_double(it->x() - nx->x());
                double dy = CGAL::to_double(it->y() - nx->y());
                if (dx*dx + dy*dy > 1e-12) ++gt_n;  // skip zero-length closing
            }
            if (gt_n != inter_poly.size() && diff_log_calls < 20) {
                std::ofstream f("/tmp/intersect_diff.txt", std::ios::app);
                f << "DIFF: orourke=" << inter_poly.size()
                  << " GT=" << gt_n
                  << " subj=" << subject.size()
                  << " clip=" << clip.size() << "\n";
                f << "  OROURKE: ";
                for (auto it = inter_poly.vertices_begin();
                     it != inter_poly.vertices_end(); ++it)
                    f << "(" << CGAL::to_double(it->x()) << ","
                      << CGAL::to_double(it->y()) << ") ";
                f << "\n  GT:       ";
                for (auto it = gt_outer.begin(); it != gt_outer.end(); ++it) {
                    const auto* nx = (it + 1 == gt_outer.end())
                                     ? &*gt_outer.begin() : &*(it + 1);
                    double dx = CGAL::to_double(it->x() - nx->x());
                    double dy = CGAL::to_double(it->y() - nx->y());
                    if (dx*dx + dy*dy <= 1e-12) continue;
                    f << "(" << CGAL::to_double(it->x()) << ","
                      << CGAL::to_double(it->y()) << ") ";
