                // Replace with GT polygon.  Build Polygon_with_holes from it.
                std::vector<Point> gt_verts;
                gt_verts.reserve(gt_outer.size());
                for (auto it = gt_outer.begin(); it != gt_outer.end(); ++it) {
                    const auto* nx = (it + 1 == gt_outer.end())
                                     ? &*gt_outer.begin() : &*(it + 1);
                    double dx = CGAL::to_double(it->x() - nx->x());
                    double dy = CGAL::to_double(it->y() - nx->y());
                    if (dx*dx + dy*dy <= 1e-12) continue;  // skip closing edge
                    gt_verts.emplace_back(CGAL::to_double(it->x()),
                                          CGAL::to_double(it->y()));
                }
                if (gt_verts.size() >= 3) {
                    Polygon gt_poly(gt_verts.begin(), gt_verts.end());
                    if (gt_poly.is_simple()) {
                        if (gt_poly.is_clockwise_oriented())
                            gt_poly.reverse_orientation();
                        *result++ = Polygon_with_holes(gt_poly);
                        gt_replaced++;
                        return;
                    }
                }
            }
        }
    } catch (...) {
        // CGAL::intersection failed — fall through to O'Rourke result.
    }

