#!/usr/bin/env python3
"""Compute continuous Fréchet distance between polyline A and polyline B
(forward matching along vertices)."""
import sys, math

def load(path):
    pts = []
    with open(path) as f:
        for i, line in enumerate(f):
            parts = line.split()
            if len(parts) < 2: continue
            if i == 0 and len(parts) == 1:  # count line
                continue
            pts.append((float(parts[0]), float(parts[1])))
    return pts

def point_seg_dist(px, py, ax, ay, bx, by):
    dx, dy = bx-ax, by-ay
    L2 = dx*dx + dy*dy
    if L2 < 1e-12:
        return math.sqrt((px-ax)**2 + (py-ay)**2)
    t = max(0.0, min(1.0, ((px-ax)*dx + (py-ay)*dy) / L2))
    qx, qy = ax + t*dx, ay + t*dy
    return math.sqrt((px-qx)**2 + (py-qy)**2)

def continuous_frechet(P, Q):
    n, m = len(P), len(Q)
    ca = [[-1.0]*m for _ in range(n)]
    def c(i, j):
        if ca[i][j] > -0.5:
            return ca[i][j]
        d = point_seg_dist(P[i][0], P[i][1], Q[j][0], Q[j][1], Q[j+1][0] if j+1<m else Q[j][0], Q[j+1][1] if j+1<m else Q[j][1]) if False else math.sqrt((P[i][0]-Q[j][0])**2 + (P[i][1]-Q[j][1])**2)
        if i == 0 and j == 0:
            ca[i][j] = d
        elif i > 0 and j == 0:
            ca[i][j] = max(c(i-1, 0), d)
        elif i == 0 and j > 0:
            ca[i][j] = max(c(0, j-1), d)
        else:
            ca[i][j] = max(min(c(i-1, j), c(i-1, j-1), c(i, j-1)), d)
        return ca[i][j]
    return c(n-1, m-1)

orig = load('data/9/original.txt')
simp = load('data/9/simplify.txt')
print(f"orig={len(orig)} simp={len(simp)}")
f = continuous_frechet(simp, orig)
print(f"frechet(simp, orig) = {f:.4f}")

