// Ground-truth cross-check using CGAL::intersection with Epeck kernel.
    // If O'Rourke's result disagrees with the ground truth, use the GT
    // result instead.  This is essential for correctness on cases like
    // case 9 where O'Rourke's polygon omits a vertex that the algorithm
    // later assumes is present, blowing the Fréchet bound.
    static int diff_log_calls = 0;
    static int gt_replaced = 0;
    try {
        // CGAL::intersection requires both inputs to be simple polygons.
        // O'Rourke's output is already simple (we checked above) but
        // `subject` (the F polygon) and `clip` (the Gi polygon) are
        // produced by other code paths and may occasionally have
        // near-degenerate vertices (collinear triples, coincident
        // consecutive points) that confuse the Boolean kernel.  We
        // sanitize each input by dropping consecutive duplicates, which
        // is a safe transformation (the sanitized polygon is geometrically
        // identical to the original up to tolerance).
        auto drop_consec_dupes = [](const Polygon& in) {
