#ifndef GEOMETRY_H
#define GEOMETRY_H

#include "simplify_geometry.h"
#include "drawing.h"

#include <array>
#include <optional>
#include <vector>

// ===========================================================================
// Algorithm parameters.  See the paper for derivation:
//   - Disk radius:       R = (1 + EPSILON/2) * DELTA
//   - Grid cell side:    g = EPSILON * DELTA / (2 * sqrt(2))
// The simplified curve is guaranteed to stay within distance R of every
// trajectory point on its associated segment.
// ===========================================================================

extern double DELTA;
extern double EPSILON;
extern const double BMIN;
extern const double BMAX;

constexpr double TOL = 1e-6;
constexpr double SQRT2 = 1.41421356237;

double GRID_val();
double R_full();
double R_val();

// ===========================================================================
// Geometry primitives (bounding box, edge classification, ray intersection).
// ===========================================================================

enum class Bbox_edge {
    BL = 0,
    BOTTOM = 1,
    BR = 2,
    RIGHT = 3,
    TR = 4,
    TOP = 5,
    TL = 6,
    LEFT = 7,
};

std::array<Point, 4> current_bbox_corner();
std::vector<Point> current_bbox();
std::optional<Bbox_edge> which_edge(const Point &s);
void append_rect_pts(std::vector<Point> &out, Bbox_edge from, Bbox_edge to,
                     bool ccw);
std::optional<Point> intersect_ray_with_rect(const Point &p,
                                             const Point &direction);

// ===========================================================================
// Grid iteration: emit all corners of cells that stab the disk of radius r
// around (px, py).  Cells are GRID x GRID squares with corners on the
// lattice {(x*GRID, y*GRID) : x, y in Z}.  A cell "stabs" the disk iff at
// least one of its four corners lies within distance r of the center.
//
// Used by `get_points_from_grid` (full list of corners) and
// `get_conv_from_grid` (just the extreme corners per row, for the convex
// hull approximation of the disk).
// ===========================================================================

template <class F>
void for_each_grid_row(double px, double py, double r, F &&f) {
    const double GRID = GRID_val();
    const double r2 = r * r;
    const int y_min = -(r / GRID) - 1;
    const int y_max = -y_min;
    for (int y = y_min; y <= y_max; y++) {
        const double y_actual = y * GRID;
        const double dy2 = y_actual * y_actual;
        if (dy2 > r2) continue;
        const double dx = std::sqrt(r2 - dy2);
        const int x_min = static_cast<int>(-dx / GRID - 1);
        const int x_max = static_cast<int>(+dx / GRID + 1);
        f(px, py, y_actual, x_min, x_max);
    }
}

std::vector<Point> get_conv_from_grid(const Point &p);
std::vector<Point> get_points_from_grid(const Point &p);

// Updated as get_points_from_grid is called; printed by simplify().
extern double expected_frechet;

// ===========================================================================
// Convex hull & polygon utilities.
// ===========================================================================

bool point_in_convex(const Point &p, const std::vector<Point> &poly,
                     bool ccw = true);

// Find the two indices on the convex polygon S that form tangent lines from p.
std::vector<int> find_tangent_idx(const Point &p, const std::vector<Point> &S);

// Build the feasible region F for the next step: cone from p through S,
// extended to the bounding box.  Returns a polygon (counter-clockwise).
std::vector<Point> find_F(const Point &p, const std::vector<Point> &S);

// O'Rourke convex polygon intersection (the algorithm proper).  Pushes the
// result into `result`.  Robust under collinear / degenerate inputs.
void intersect(const Polygon &subject, const Polygon &clip,
               std::back_insert_iterator<std::vector<Polygon_with_holes>> result);

// ===========================================================================
// Top-level simplification.
// ===========================================================================

int get_longest_stab(const std::vector<Point> &stream, int cur,
                     std::vector<Point> &simplified,
                     MultiViewer *viewer = nullptr);

std::vector<Point> simplify(const std::vector<Point> &stream,
                            MultiViewer *viewer = nullptr);

// ===========================================================================
// CLI flags shared with main().  Defaults are set in geometry.cpp.
// ===========================================================================

extern bool showF;
extern bool showG;
extern bool showS;
extern bool out_flag;
extern bool gui_flag;
extern bool dist_flag;

#endif // GEOMETRY_H

#include "geometry.h"
#include "timer.h"

#include <CGAL/convex_hull_2.h>
#include <CGAL/Boolean_set_operations_2.h>
#include <CGAL/intersections.h>

#include <cmath>
#include <iostream>
#include <vector>
#include <cassert>

// ===========================================================================
// CLI flag defaults (overridden by main() in simplify.cpp).
// ===========================================================================

bool showF = false;
bool showG = false;
bool showS = false;
bool out_flag = false;
bool gui_flag = false;
bool dist_flag = false;

// ===========================================================================
// Algorithm parameters.
// ===========================================================================

extern const double BMIN = -10000;
extern const double BMAX = 10000;

// TODO: DELTA should not be too high that convex hull goes out of bounding square.
double DELTA = 200;
double EPSILON = 0.6;

double GRID_val() { return EPSILON * DELTA / (2 * SQRT2); }

// Disk radius: theoretical bound on the Fréchet distance of any simplified
// segment from its associated trajectory point.  Used both for the grid
// corner listing (get_points_from_grid, get_conv_from_grid) and as the
// algorithm's feasible region radius — they're the same.
double R_full() { return (1.0 + EPSILON / 2.0) * DELTA; }
double R_val() { return R_full(); }

// ===========================================================================
// Signed polygon area (used by O'Rourke's main loop).
// ===========================================================================

static double kernel_signed_area(const std::vector<Point>& P) {
    double s = 0.0;
    int sz = (int)P.size();
    for (int i = 0; i < sz; ++i) {
        const Point& a = P[i];
        const Point& b = P[(i + 1) % sz];
        s += CGAL::to_double(a.x() * b.y() - b.x() * a.y());
    }
    return s / 2.0;
}

// ===========================================================================
//  O'Rourke's ConvexIntersect (Ch. 7, "Computational Geometry in C", 2nd ed.)
// ===========================================================================
namespace orourke_cgal {

enum class InFlag { Pin, Qin, Unknown };

static int area_sign(const Point& a, const Point& b, const Point& c) {
    switch (CGAL::orientation(a, b, c)) {
        case CGAL::LEFT_TURN:  return  1;
        case CGAL::RIGHT_TURN: return -1;
        case CGAL::COLLINEAR:  return  0;
    }
    return 0;
}

static int area_sign_vec(const Vector& a, const Vector& b) {
    auto c = CGAL::determinant(a, b);
    if (c > 0) return  1;
    if (c < 0) return -1;
    return 0;
}

static bool between(const Point& a, const Point& b, const Point& c) {
    if (CGAL::orientation(a, b, c) != CGAL::COLLINEAR) return false;
    if (CGAL::abs(b.x() - a.x()) >= CGAL::abs(b.y() - a.y())) {
        return (a.x() <= c.x() && c.x() <= b.x()) ||
               (a.x() >= c.x() && c.x() >= b.x());
    }
    return (a.y() <= c.y() && c.y() <= b.y()) ||
           (a.y() >= c.y() && c.y() >= b.y());
}

static int dot_sign(const Point& a, const Point& b,
                    const Point& c, const Point& d) {
    auto dot = CGAL::scalar_product(b - a, d - c);
    if (dot > 0) return  1;
    if (dot < 0) return -1;
    return 0;
}

static char parallel_int(const Point& a, const Point& b,
                         const Point& c, const Point& d, Point& p) {
    // Assumes ab and cd are parallel and not collinear.
    if (CGAL::orientation(a, b, c) != CGAL::COLLINEAR) return '0';
    if (!between(a, b, c)) return '0';
    p = c;
    return 'e';
}

static int advance(int a, int& aa, int n, bool inside,
                   const Point& /*v*/, std::vector<Point>& /*out*/) {
    if (inside)
        ++aa;
    return (a + 1) % n;
}

static InFlag in_out(const Point& /*p*/, InFlag inflag, int aHB, int bHA) {
    if (aHB > 0)
        return InFlag::Pin;
    else if (bHA > 0)
        return InFlag::Qin;
    return inflag;
}

static bool point_in_convex_poly(const Point& p, const std::vector<Point>& poly) {
    int n = (int)poly.size();
    if (n < 3) return false;
    int sign = 0;
    for (int i = 0; i < n; ++i) {
        int s = area_sign(poly[i], poly[(i + 1) % n], p);
        if (s == 0) continue;
        if (sign == 0) sign = s;
        else if (sign != s) return false;
    }
    return true;
}

static bool all_points_in_convex_poly(const std::vector<Point>& inner,
                                      const std::vector<Point>& outer) {
    for (const auto& p : inner)
        if (!point_in_convex_poly(p, outer)) return false;
    return true;
}

static std::optional<Point> line_intersect(const Point& a, const Point& b,
                                           const Point& c, const Point& d) {
    auto inter = CGAL::intersection(Segment(a, b), Segment(c, d));
    if (!inter) return std::nullopt;
    if (const Point* ip = std::get_if<Point>(&*inter)) return *ip;
    return std::nullopt;
}

// Clip a convex polygon `subject` by a half-plane defined by line `a -> b`,
// keeping the LEFT side (orientation-positive).
static std::vector<Point> clip_halfplane(const std::vector<Point>& subject,
                                         const Point& a, const Point& b) {
    std::vector<Point> out;
    int n = (int)subject.size();
    for (int i = 0; i < n; ++i) {
        const Point& cur  = subject[i];
        const Point& next = subject[(i + 1) % n];
        bool cur_in  = CGAL::orientation(a, b, cur)  != CGAL::RIGHT_TURN;
        bool next_in = CGAL::orientation(a, b, next) != CGAL::RIGHT_TURN;
        if (cur_in) out.push_back(cur);
        if (cur_in != next_in) {
            if (auto ip = line_intersect(cur, next, a, b)) out.push_back(*ip);
        }
    }
    return out;
}

static std::vector<Point> convex_intersect_fast(const std::vector<Point>& Pin,
                                                const std::vector<Point>& Qin) {
    std::vector<Point> P = Pin, Q = Qin;
    if (kernel_signed_area(P) < 0) std::reverse(P.begin(), P.end());
    if (kernel_signed_area(Q) < 0) std::reverse(Q.begin(), Q.end());
    for (int i = 0; i < (int)P.size(); ++i) {
        Point a = P[i], b = P[(i + 1) % P.size()];
        Q = clip_halfplane(Q, a, b);
        if (Q.empty()) return {};
    }
    if (Q.empty()) return {};
    return Q;
}

static std::vector<Point> convex_intersect(const std::vector<Point>& Pin,
                                           const std::vector<Point>& Qin) {
    int n = (int)Pin.size();
    int m = (int)Qin.size();
    if (n < 3 || m < 3) return {};

    auto signed_area = [](const std::vector<Point>& P) {
        return kernel_signed_area(P);
    };
    auto leftmost_index = [](const std::vector<Point>& P) {
        int best = 0;
        for (int i = 1; i < (int)P.size(); ++i) {
            if (CGAL::compare_y(P[i], P[best]) == CGAL::SMALLER ||
                (CGAL::compare_y(P[i], P[best]) == CGAL::EQUAL &&
                 CGAL::compare_x(P[i], P[best]) == CGAL::SMALLER)) {
                best = i;
            }
        }
        return best;
    };
    std::vector<Point> Pr = Pin, Qr = Qin;
    if (signed_area(Pr) < 0) std::reverse(Pr.begin(), Pr.end());
    if (signed_area(Qr) < 0) std::reverse(Qr.begin(), Qr.end());
    int a = leftmost_index(Pr);
    int b = leftmost_index(Qr);

    int aa = 0, ba = 0;
    InFlag inflag = InFlag::Unknown;
    bool first_point = true;
    Point p0;

    std::vector<Point> out;

    do {
        int a1 = (a + n - 1) % n;
        int b1 = (b + m - 1) % m;

        Vector A = Pr[a] - Pr[a1];
        Vector B = Qr[b] - Qr[b1];

        int cross  = area_sign_vec(A, B);
        int aHB    = area_sign(Qr[b1], Qr[b], Pr[a]);
        int bHA    = area_sign(Pr[a1], Pr[a], Qr[b]);

        Point p, q;
        char code;
        {
            Epick::Segment_2 seg_a(Pr[a1], Pr[a]);
            Epick::Segment_2 seg_b(Qr[b1], Qr[b]);
            auto inter = CGAL::intersection(seg_a, seg_b);
            if (!inter) {
                code = '0';
            } else if (const Epick::Segment_2* seg =
                           std::get_if<Epick::Segment_2>(&*inter)) {
                p = seg->source();
                q = seg->target();
                code = 'e';
            } else if (const Epick::Point_2* ip =
                           std::get_if<Epick::Point_2>(&*inter)) {
                p = *ip;
                bool on_seg_a = (CGAL::orientation(Pr[a1], Pr[a], p) == CGAL::COLLINEAR);
                bool on_seg_b = (CGAL::orientation(Qr[b1], Qr[b], p) == CGAL::COLLINEAR);
                if (!on_seg_a || !on_seg_b) {
                    Epeck::Segment_2 eseg_a(conv_to_exact(Pr[a1]), conv_to_exact(Pr[a]));
                    Epeck::Segment_2 eseg_b(conv_to_exact(Qr[b1]), conv_to_exact(Qr[b]));
                    auto einter = CGAL::intersection(eseg_a, eseg_b);
                    if (einter) {
                        if (const Epeck::Point_2* ep =
                                std::get_if<Epeck::Point_2>(&*einter))
                            p = conv_to_inexact(*ep);
                        else if (const Epeck::Segment_2* es =
                                     std::get_if<Epeck::Segment_2>(&*einter)) {
                            p = conv_to_inexact(es->source());
                            q = conv_to_inexact(es->target());
                        }
                    }
                }
                if (p == Qr[b1] || p == Qr[b] || p == Pr[a1] || p == Pr[a])
                    code = 'v';
                else
                    code = '1';
            } else {
                code = '0';
            }
        }

        if (code == '1' || code == 'v') {
            if (inflag == InFlag::Unknown && first_point) {
                aa = ba = 0;
                first_point = false;
                p0 = p;
            }
            out.push_back(p);
            inflag = in_out(p, inflag, aHB, bHA);
        }

        if ((code == 'e') && (dot_sign(Pr[a1], Pr[a], Qr[b1], Qr[b]) < 0)) {
            out.push_back(p);
            out.push_back(q);
            return out;
        }

        if ((cross == 0) && (aHB < 0) && (bHA < 0)) {
            return {};
        }

        if ((cross == 0) && (aHB == 0) && (bHA == 0)) {
            if (inflag == InFlag::Pin)
                b = advance(b, ba, m, inflag == InFlag::Qin, Qr[b], out);
            else
                a = advance(a, aa, n, inflag == InFlag::Pin, Pr[a], out);
        } else if (cross >= 0) {
            if (bHA > 0)
                a = advance(a, aa, n, inflag == InFlag::Pin, Pr[a], out);
            else
                b = advance(b, ba, m, inflag == InFlag::Qin, Qr[b], out);
        } else {
            if (aHB > 0)
                b = advance(b, ba, m, inflag == InFlag::Qin, Qr[b], out);
            else
                a = advance(a, aa, n, inflag == InFlag::Pin, Pr[a], out);
        }
    } while (((aa < n) || (ba < m)) && (aa < 2 * n) && (ba < 2 * m));

    if (first_point) {
        if (point_in_convex_poly(Pr[0], Qr)) return Pr;
        if (point_in_convex_poly(Qr[0], Pr)) return Qr;
        return {};
    }

    out.push_back(p0);
    return out;
}

}  // namespace orourke_cgal

// ===========================================================================
// Intersect wrapper: O'Rourke's convex polygon intersection, with a
// ground-truth (Epeck) cross-check for tiny results.  Tiny results (≤8
// vertices) are where O'Rourke tends to go wrong on edge cases, so we
// verify them with CGAL::intersection.
// ===========================================================================

void intersect(const Polygon& subject, const Polygon& clip,
               std::back_insert_iterator<std::vector<Polygon_with_holes>> result) {
    std::vector<Point> P_verts, Q_verts;
    {
        TIMER("copy_verts");
        P_verts.reserve(subject.size());
        Q_verts.reserve(clip.size());
        for (auto it = subject.vertices_begin(); it != subject.vertices_end(); ++it) {
            P_verts.push_back(*it);
        }
        for (auto it = clip.vertices_begin(); it != clip.vertices_end(); ++it) {
            Q_verts.push_back(*it);
        }
    }

    std::vector<Point> verts;
    {
        TIMER("convex_intersect");
        verts = orourke_cgal::convex_intersect(P_verts, Q_verts);
    }
    if (verts.size() < 4) return;
    if (verts.front() == verts.back())
        verts.pop_back();

    Polygon inter_poly(verts.begin(), verts.end());
    if (!inter_poly.is_simple()) return;
    {
        size_t distinct = 0;
        for (auto it = inter_poly.vertices_begin();
             it != inter_poly.vertices_end(); ++it) {
            auto nx = it;
            ++nx;
            if (nx == inter_poly.vertices_end()) nx = inter_poly.vertices_begin();
            double dx = CGAL::to_double(it->x() - nx->x());
            double dy = CGAL::to_double(it->y() - nx->y());
            if (dx*dx + dy*dy > 1e-12) ++distinct;
        }
        if (distinct < 3) return;
    }
    if (inter_poly.is_clockwise_oriented()) inter_poly.reverse_orientation();

    if (inter_poly.size() <= 8) {
        Polygon sub_epick(subject.begin(), subject.end());
        Polygon clp_epick(clip.begin(), clip.end());
        if (sub_epick.is_simple() && clp_epick.is_simple()) {
            try {
                using EpeckPoly = CGAL::Polygon_2<CGAL::Epeck>;
                using EpeckPWH  = CGAL::Polygon_with_holes_2<CGAL::Epeck>;
                EpeckPoly sub_poly, clp_poly;
                for (const auto& p : sub_epick)
                    sub_poly.push_back(CGAL::Epeck::Point_2(p.x(), p.y()));
                for (const auto& p : clp_epick)
                    clp_poly.push_back(CGAL::Epeck::Point_2(p.x(), p.y()));
                std::vector<EpeckPWH> gt_pwh;
                CGAL::intersection(sub_poly, clp_poly, std::back_inserter(gt_pwh));
                if (!gt_pwh.empty()) {
                    const auto& gt_outer = gt_pwh[0].outer_boundary();
                    size_t gt_n = 0;
                    for (auto it = gt_outer.begin(); it != gt_outer.end(); ++it) {
                        auto next_it = it; ++next_it;
                        if (next_it == gt_outer.end()) next_it = gt_outer.begin();
                        double dx = CGAL::to_double(it->x() - next_it->x());
                        double dy = CGAL::to_double(it->y() - next_it->y());
                        if (dx*dx + dy*dy > 1e-12) ++gt_n;
                    }
                    if (gt_n != inter_poly.size() && gt_n >= 3) {
                        std::vector<Point> gt_verts;
                        gt_verts.reserve(gt_outer.size());
                        for (auto it = gt_outer.begin(); it != gt_outer.end(); ++it) {
                            auto next_it = it; ++next_it;
                            if (next_it == gt_outer.end()) next_it = gt_outer.begin();
                            double dx = CGAL::to_double(it->x() - next_it->x());
                            double dy = CGAL::to_double(it->y() - next_it->y());
                            if (dx*dx + dy*dy <= 1e-12) continue;
                            gt_verts.emplace_back(CGAL::to_double(it->x()),
                                                  CGAL::to_double(it->y()));
                        }
                        if (gt_verts.size() >= 3) {
                            Polygon gt_poly(gt_verts.begin(), gt_verts.end());
                            if (gt_poly.is_simple()) {
                                if (gt_poly.is_clockwise_oriented())
                                    gt_poly.reverse_orientation();
                                *result++ = Polygon_with_holes(gt_poly);
                                return;
                            }
                        }
                    }
                }
            } catch (...) {
                // Fall through to O'Rourke.
            }
        }
    }
    *result++ = Polygon_with_holes(inter_poly);
}

// ===========================================================================
// Geometry primitives: bounding box, edge classification, ray intersection.
// ===========================================================================

std::array<Point, 4> current_bbox_corner() {
    return {Point(BMIN, BMIN), Point(BMAX, BMIN), Point(BMAX, BMAX),
            Point(BMIN, BMAX)};
}

std::vector<Point> current_bbox() {
    auto c = current_bbox_corner();
    return std::vector<Point>(c.begin(), c.end());
}

std::optional<Bbox_edge> which_edge(const Point &s) {
    double x = CGAL::to_double(s.x()), y = CGAL::to_double(s.y());
    bool on_left   = std::abs(x - BMIN) < TOL;
    bool on_right  = std::abs(x - BMAX) < TOL;
    bool on_bottom = std::abs(y - BMIN) < TOL;
    bool on_top    = std::abs(y - BMAX) < TOL;

    if (on_left && on_bottom) return Bbox_edge::BL;
    if (on_right && on_bottom) return Bbox_edge::BR;
    if (on_right && on_top) return Bbox_edge::TR;
    if (on_left && on_top) return Bbox_edge::TL;

    if (on_bottom) return Bbox_edge::BOTTOM;
    if (on_right)  return Bbox_edge::RIGHT;
    if (on_top)    return Bbox_edge::TOP;
    if (on_left)   return Bbox_edge::LEFT;
    return std::nullopt;
}

void append_rect_pts(std::vector<Point> &out, Bbox_edge from, Bbox_edge to,
                     bool ccw) {
    auto corners = current_bbox_corner();

    auto next = [&](int idx) {
        return (idx + (ccw ? 1 : 7)) % 8;
    };

    int i = static_cast<int>(from);
    int j = static_cast<int>(to);
    if (i == j) return;
    for (int k = next(i); k != j; k = next(k)) {
        if ((k & 1) == 0) {
            int ci = k / 2;
            out.push_back(corners[ci]);
        }
    }
}

std::optional<Point> intersect_ray_with_rect(const Point& p, const Point& direction) {
    if (CGAL::to_double(CGAL::squared_distance(p, direction)) < TOL*TOL) return std::nullopt;

    Ray ray(p, direction);
    Bbox box(BMIN, BMIN, BMAX, BMAX);

    if (auto obj = CGAL::intersection(Rect(box), ray)) {
        if (const Point* ip = std::get_if<Point>(&*obj)) {
            if (CGAL::to_double(CGAL::squared_distance(*ip, p)) < TOL*TOL) return std::nullopt;
            return *ip;
        }
        if (const Segment* seg = std::get_if<Segment>(&*obj)) {
            const Point& a = seg->source();
            const Point& b = seg->target();
            double da = CGAL::to_double(CGAL::squared_distance(a, p));
            double db = CGAL::to_double(CGAL::squared_distance(b, p));
            if (da < TOL*TOL) return b;
            if (db < TOL*TOL) return a;
            return (da < db) ? a : b;
        }
    }
    return std::nullopt;
}

bool point_in_convex(const Point &p, const std::vector<Point> &poly, bool ccw) {
    for (size_t i = 0, n = poly.size(); i < n; ++i) {
        const auto &a = poly[i];
        const auto &b = poly[(i + 1) % n];
        if (CGAL::orientation(a, b, p) == (ccw ? CGAL::RIGHT_TURN : CGAL::LEFT_TURN))
            return false;
    }
    return true;
}

// ===========================================================================
// Grid iteration: corners of cells that stab the disk of radius r around p.
// ===========================================================================

double expected_frechet = 0;

std::vector<Point> get_points_from_grid(const Point &p) {
    const double px = CGAL::to_double(p.x());
    const double py = CGAL::to_double(p.y());
    const double r = R_full();
    const double GRID = GRID_val();
    if (DELTA == 0) {
        return std::vector<Point>{p};
    }
    std::vector<Point> points;
    for_each_grid_row(px, py, r, [&](double px_, double py_,
                                  double y_actual, int x_min, int x_max) {
        for (int x = x_min; x <= x_max; x++) {
            points.emplace_back(px_ + x * GRID, py_ + y_actual);
            expected_frechet = std::max(expected_frechet, CGAL::to_double(CGAL::squared_distance(p, points.back())));
        }
    });
    return points;
}

std::vector<Point> get_conv_from_grid(const Point &p) {
    const double px = CGAL::to_double(p.x());
    const double py = CGAL::to_double(p.y());
    const double r = R_val();
    std::vector<Point> boundaries;
    for_each_grid_row(px, py, r, [&](double px_, double py_,
                                  double y_actual, int x_min, int x_max) {
        boundaries.emplace_back(px_ + x_min * GRID_val(), py_ + y_actual);
        if (x_max != 0)
            boundaries.emplace_back(px_ + x_max * GRID_val(), py_ + y_actual);
    });
    std::vector<Point> conv;
    CGAL::convex_hull_2(boundaries.begin(), boundaries.end(),
                        std::back_inserter(conv));
    return conv;
}

// ===========================================================================
// Tangent finding and feasible-region construction.
// ===========================================================================

std::vector<int> find_tangent_idx(const Point &p, const std::vector<Point> &S) {
    int n = S.size();
    std::vector<int> tangent;
    {
        TIMER("find_tangent_idx");
        tangent.reserve(2);

        auto orient_at = [&](int i) {
            return CGAL::orientation(p, S[i], S[(i + 1) % n]);
        };

        int prev = orient_at(n - 1);
        for (int i = 0; i < n; ++i) {
            int cur = orient_at(i);
            if (cur != prev && cur != CGAL::COLLINEAR) {
                tangent.push_back(i);
                if (tangent.size() == 2) break;
            }
            prev = cur;
        }
    }
    return tangent;
}

std::vector<Point> find_F(const Point& p, const std::vector<Point>& S) {
    assert(S.size() != 2);
    if (S.size() == 1) {
        return current_bbox();
    }
    if (point_in_convex(p, S)) {
        return current_bbox();
    }
    std::vector<int> tangent = find_tangent_idx(p, S);
    assert(tangent.size() == 2);

    std::optional<Point> hit1, hit2;
    {
        TIMER("ray_hits");
        hit1 = intersect_ray_with_rect(p, S[tangent[0]]);
        hit2 = intersect_ray_with_rect(p, S[tangent[1]]);
    }
    if (!hit1 || !hit2) {
        std::cerr << "Ray doesn't intersect with bounding box!\n";
        return current_bbox();
    }
    std::optional<Bbox_edge> e1 = which_edge(hit1.value());
    std::optional<Bbox_edge> e2 = which_edge(hit2.value());

    int n = int(S.size());
    assert(n >= 3);
    CGAL_precondition(Polygon(S.begin(), S.end()).is_counterclockwise_oriented());
    assert(tangent[1] - tangent[0] - 1 >= 1 || tangent[0] + n - tangent[1] - 1 >= 1);
    std::vector<Point> F;
    {
        TIMER("build_F_poly");
        if (CGAL::right_turn(p, S[tangent[0]], S[tangent[1]]))  {
            std::copy(S.begin() + tangent[0], S.begin() + tangent[1] + 1,
                      std::back_inserter(F));
            F.push_back(hit2.value());
            append_rect_pts(F, e2.value(), e1.value(), true);
            F.push_back(hit1.value());
        } else {
            std::copy(S.begin() + tangent[1], S.end(),
                      std::back_inserter(F));
            std::copy(S.begin(), S.begin() + tangent[0] + 1,
                      std::back_inserter(F));
            F.push_back(hit1.value());
            append_rect_pts(F, e1.value(), e2.value(), true);
            F.push_back(hit2.value());
        }
    }
    if (!e1 || !e2) {
        std::cerr << "Cannot determine which Bbox edge the ray intersect with.\n";
        return current_bbox();
    }
    return F;
}

// ===========================================================================
// Top-level simplification: iterate stabs until exhausted.
// ===========================================================================

int get_longest_stab(const std::vector<Point> &stream, int cur,
                     std::vector<Point> &simplified, MultiViewer* viewer) {
    TIMER("get_longest_stab");
    const Point& p0 = stream[cur];
    std::vector<Point> P;
    {
        TIMER("get_points_from_grid");
        P = get_points_from_grid(p0);
    }
    if (viewer) {
        TIMER("gui_update");
        viewer->markP0(p0);
        viewer->addOriginalPoint(p0);
    }
    std::array<Point, 2> buffer = {p0, p0};
    std::vector<std::vector<Point>> S(P.size(), std::vector<Point>{p0});
    std::vector<int> dead(P.size());
    int dead_cnt = 0;
    cur++;
    while (cur < int(stream.size())) {
        const Point& pi  = stream[cur];
        std::vector<Point> Gi;
        {
            TIMER("get_conv_from_grid");
            Gi = get_conv_from_grid(pi);
        }
        std::vector<std::vector<Polygon_with_holes>> new_S(P.size());
        for (int i = 0; i < int(P.size()); i++) {
            if (dead[i]) continue;
            std::vector<Point> F;
            Polygon F_poly, Gi_poly, S_poly;
            {
                TIMER("find_F");
                F = find_F(P[i], S[i]);
            }
            {
                TIMER("polygon_construction");
                F_poly = Polygon(F.begin(), F.end());
                Gi_poly = Polygon(Gi.begin(), Gi.end());
                S_poly = Polygon(S[i].begin(), S[i].end());
            }

            if (i == 0) {
                const QColor stepColors[] = {
                    Qt::red, Qt::blue, Qt::green, Qt::magenta, Qt::cyan
                };
                QColor c = stepColors[cur % 6];
                if (viewer) {
                    TIMER("gui_update");
                    if (showF) viewer->addPolygon(F_poly, c);
                    if (showG) viewer->addPolygon(Gi_poly, c);
                    if (showS) viewer->addPolygon(S_poly, c);
                }
            }

            {
                TIMER("intersect");
                intersect(F_poly, Gi_poly, back_inserter(new_S[i]));
            }

            if (new_S[i].size() == 0) {
                dead[i] = true;
                dead_cnt++;
                continue;
            }
            assert(new_S[i].size() == 1);
            buffer[0] = P[i];
            // Pick the vertex of F ∩ Gi furthest from P[i].  Extending the
            // simplified segment as far as the feasible region allows is
            // critical for keeping the segment within Fréchet bound (see
            // case 9 — random bbox vertices blow the bound).
            {
                const auto& outer = new_S[i].begin()->outer_boundary();
                double best_d2 = -1.0;
                Point best_pt = outer.is_empty() ? P[i] : *outer.vertices_begin();
                for (auto it = outer.vertices_begin(); it != outer.vertices_end(); ++it) {
                    double dx = CGAL::to_double(it->x() - P[i].x());
                    double dy = CGAL::to_double(it->y() - P[i].y());
                    double d2 = dx*dx + dy*dy;
                    if (d2 > best_d2) {
                        best_d2 = d2;
                        best_pt = *it;
                    }
                }
                buffer[1] = best_pt;
            }
        }
        if (dead_cnt == int(P.size())) break;
        if (viewer) {
            TIMER("gui_update");
            viewer->addOriginalPoint(pi);
            viewer->markPi(pi);
        }
        {
            TIMER("update_S");
            for (int i = 0; i < int(P.size()); i++) {
                if (dead[i]) continue;
                S[i].clear();
                std::copy(new_S[i].begin()->outer_boundary().vertices_begin(),
                          new_S[i].begin()->outer_boundary().vertices_end(),
                          std::back_inserter(S[i]));
            }
        }
        cur++;
        if (viewer) {
            TIMER("gui_update");
            viewer_process_events();
        }
    }
    simplified.emplace_back(buffer[0]);
    simplified.emplace_back(buffer[1]);
    if (viewer) {
        TIMER("gui_update");
        viewer->addSimplifiedPoint(buffer[0]);
        viewer->addSimplifiedPoint(buffer[1]);
        viewer->clearPolygons();
        viewer->clearMarkedP0();
        viewer->clearMarkedPi();
        viewer_process_events();
    }
    return cur;
}

std::vector<Point> simplify(const std::vector<Point> &stream, MultiViewer* viewer) {
