std::vector<Point> get_points_from_grid(const Point &p) {
    const double px = CGAL::to_double(p.x());
    const double py = CGAL::to_double(p.y());
    const double r = R_full();
    const double GRID = GRID_val();
    if (DELTA == 0) {
        return std::vector<Point>{p};
    }
    // A grid cell "stabs" the disk iff its CENTER is within distance r of p.
    // Equivalently: cell (j, k) (with corners at (j*GRID, k*GRID) etc.) stabs
    // iff sqrt((j+0.5)^2 + (k+0.5)^2) <= r/GRID.  We then emit all four
    // corners of every stab cell; a corner (j*GRID, k*GRID) is emitted if any
    // of the four cells sharing it stabs, i.e., if any of
    //   (j-0.5)^2 + (k-0.5)^2
    //   (j+0.5)^2 + (k-0.5)^2
    //   (j-0.5)^2 + (k+0.5)^2
    //   (j+0.5)^2 + (k+0.5)^2
    // is <= (r/GRID)^2.
    //
    // The farthest such corner is at distance r + GRID*sqrt(2)/2 from p (the
    // farthest corner of a cell whose center is at distance r from p).
    // For the test parameters e=0.5, d=200 (R=250, GRID=100/sqrt(2)),
    // cell (2,2)'s center is exactly at distance 250, so cell (2,2) stabs
    // and its TR corner (3*GRID, 3*GRID) lands at distance 300 — matching
    // the theoretical Fréchet bound (1 + e) * d.
    const double ratio = r / GRID;
    const double ratio2 = ratio * ratio;
    const int M = static_cast<int>(std::ceil(ratio)) + 2;
    std::vector<Point> points;
    for (int j = -M; j <= M; j++) {
        for (int k = -M; k <= M; k++) {
            // Four candidate cell centers adjacent to corner (j, k):
            const double jm = j - 0.5, jp = j + 0.5;
            const double km = k - 0.5, kp = k + 0.5;
            bool stab =
                (jm*jm + km*km <= ratio2) ||
                (jp*jp + km*km <= ratio2) ||
                (jm*jm + kp*kp <= ratio2) ||
                (jp*jp + kp*kp <= ratio2);
            if (!stab) continue;
            points.emplace_back(px + j * GRID, py + k * GRID);
            expected_frechet = std::max(expected_frechet,
                CGAL::to_double(CGAL::squared_distance(p, points.back())));
        }
    }
    return points;
}

