static void intersect(const std::vector<Point>& P_verts, const std::vector<Point>& Q_verts,
                        std::back_insert_iterator<std::vector<Polygon_with_holes>> result) {
    {
        static struct SizeStats {
            long long calls = 0, sumP = 0, sumQ = 0, sumPQ = 0;
            size_t maxP = 0, maxQ = 0;
            ~SizeStats() {
                if (calls == 0) return;
                std::cerr << "[intersect sizes] calls=" << calls
                          << " avg|P|=" << (double)sumP / calls
                          << " avg|Q|=" << (double)sumQ / calls
                          << " avg(|P|+|Q|)=" << (double)sumPQ / calls
                          << " max|P|=" << maxP << " max|Q|=" << maxQ << "\n";
            }
        } stats;
        stats.calls++;
        stats.sumP += (long long)P_verts.size();
        stats.sumQ += (long long)Q_verts.size();
        stats.sumPQ += (long long)(P_verts.size() + Q_verts.size());
        stats.maxP = std::max(stats.maxP, P_verts.size());
        stats.maxQ = std::max(stats.maxQ, Q_verts.size());
    }
    std::vector<Point> verts;
    {
        TIMER("convex_intersect");
        verts = orourke_cgal::convex_intersect(P_verts, Q_verts);
    }

