// Intersection point of line ab and line cd, constructed in fast double
// arithmetic.  The caller must have already established (via exact predicates)
// that the two lines are NOT parallel, so `denom` is non-zero.  A point is a
// *construction*, not a predicate: double here produces the exact same value
// Epick would, but without allocating CGAL::intersection's variant.
static Point line_point(const Point& a, const Point& b,
                        const Point& c, const Point& d) {
    double ax = CGAL::to_double(a.x()), ay = CGAL::to_double(a.y());
    double bx = CGAL::to_double(b.x()), by = CGAL::to_double(b.y());
    double cx = CGAL::to_double(c.x()), cy = CGAL::to_double(c.y());
    double dx = CGAL::to_double(d.x()), dy = CGAL::to_double(d.y());
    double rx = bx - ax, ry = by - ay;
    double sx = dx - cx, sy = dy - cy;
    double denom = rx * sy - ry * sx;
    double t = ((cx - ax) * sy - (cy - ay) * sx) / denom;
    return Point(ax + t * rx, ay + t * ry);
}

// Robust segment-segment intersection, O'Rourke's SegSegInt classification.
// The combinatorial decision (which of '0','1','v','e') is made entirely from
// exact orientation predicates, so it is bit-identical to a full-Epeck run and
// the Frechet bound stays correct even on near-collinear input.  Only the
// intersection POINT is constructed in double.
//
// This replaces the previous per-iteration CGAL::intersection(Segment,Segment)
// construction, which allocated a std::variant, internally recomputed
// predicates, and fell back to Epeck ~8.5% of the time.  Return codes match:
//   '0' no intersection
//   '1' proper crossing (point in p)
//   'v' an endpoint of one segment lies on the other (point in p)
//   'e' collinear overlap (endpoints in p, q)
static char seg_seg_int(const Point& a, const Point& b,
                        const Point& c, const Point& d,
                        Point& p, Point& q) {
    int d1 = area_sign(c, d, a);
    int d2 = area_sign(c, d, b);
    int d3 = area_sign(a, b, c);
    int d4 = area_sign(a, b, d);

    // Proper crossing: a,b strictly on opposite sides of line cd AND c,d
    // strictly on opposite sides of line ab.
    if (((d1 > 0 && d2 < 0) || (d1 < 0 && d2 > 0)) &&
        ((d3 > 0 && d4 < 0) || (d3 < 0 && d4 > 0))) {
        p = line_point(a, b, c, d);
        return '1';
    }

    // All four collinear: parallel/overlap case -> possibly 'e'.
    if (d1 == 0 && d2 == 0 && d3 == 0 && d4 == 0) {
        return parallel_int(a, b, c, d, p, q);
    }

    // Endpoint-touching ('v'): one endpoint is collinear with and lies on the
    // other segment.  Exact predicates decide this, not a double coordinate
    // comparison — that is precisely what keeps double from misclassifying.
    if (d1 == 0 && between(c, d, a)) { p = a; return 'v'; }
    if (d2 == 0 && between(c, d, b)) { p = b; return 'v'; }
    if (d3 == 0 && between(a, b, c)) { p = c; return 'v'; }
    if (d4 == 0 && between(a, b, d)) { p = d; return 'v'; }
    return '0';
}

